"""Original introductory-college course packets: full-length practice for a
real college class session (75-180 minutes depending on course format, not
a K-12 block period). Every passage/dialogue, problem set, and answer below
is original content written for this batch; no textbook or copyrighted
course material is reproduced. Replaces the 8 short (6-8 page, 16-item)
drafts a prior pass shipped, which were sized for a K-12 activity, not a
college session.
"""
SOURCE = 'Course-level learning objective written for this packet; no accreditation, transfer credit, or universal course-equivalency is claimed.'
ROWS = []


def add(slug, title, course, subject, code, standard_text, objective, lesson, models, texts, items, minutes, price, vocab=None, pacing=None, text_font=None, compositions=None):
    assert len(items) == 20, (slug, len(items))
    assert len(models) == 2
    assert len(texts) in (1, 2), (slug, len(texts))
    ROWS.append(dict(id='college-' + slug, title=title, course=course, subject=subject,
        standard=code + ' — ' + standard_text, objective=objective, source=SOURCE,
        resourceType='Complete course practice packet',
        lesson=lesson, models=models, texts=texts, vocab=vocab or [], pacing=pacing, text_font=text_font,
        compositions=compositions,
        items=[{'q': q, 'answer': a, 'work': a} for q, a in items], minutes=minutes, price=price))


# ---------------------------------------------------------------- French 101
add('french101-cafe', 'French 101: Café de la Place — A Full Conversation Session', 'French 101', 'French',
 'COURSE-OBJ.FR101.2',
 'Exchange greetings, personal information, and café requests using polite expressions, articles, and the present tense of être, avoir, and -er verbs.',
 'Use beginner French accurately and politely to greet, introduce yourself, order at a café, and ask simple questions about people and preferences.',
 'Être (to be) and avoir (to have) are irregular and among the most frequent verbs in French; most other present-tense verbs follow the regular -er pattern (parler → je parle, tu parles, il/elle parle, nous parlons, vous parlez, ils/elles parlent). Definite articles (le, la, les) and indefinite articles (un, une, des) must agree in gender and number with the noun. Politeness markers (s\'il vous plaît, merci, vouvoiement with vous) are expected in service and academic contexts.',
 [('Conjugate parler for je, nous, and ils.', 'je parle, nous parlons, ils parlent — regular -er pattern: drop -er, add -e, -ons, -ent.'),
  ('Why does "café" take "un" but "eau" typically appears as "une eau" in a request?', '"Café" is a masculine noun so it pairs with "un"; "eau" is feminine, so it pairs with "une" — gender is a property of the noun itself, not something chosen freely.')],
 [('Au Café de la Place (Partie 1)', (
   'SERVEUR : Bonjour ! Bienvenue au Café de la Place. Vous êtes combien ?\n\n'
   'INÈS : Bonjour, monsieur. Nous sommes deux. Mon ami et moi, nous avons rendez-vous avec notre professeur.\n\n'
   'SERVEUR : Très bien. Une table près de la fenêtre ?\n\n'
   'MARCUS : Oui, s\'il vous plaît. C\'est parfait.\n\n'
   'SERVEUR : Voici le menu. Vous désirez boire quelque chose ?\n\n'
   'INÈS : Je voudrais un café, s\'il vous plaît. Et toi, Marcus ?\n\n'
   'MARCUS : Moi, je voudrais un thé et un croissant. J\'ai très faim ce matin.\n\n'
   'SERVEUR : Très bien. Et pour vous, mademoiselle ?\n\n'
   'INÈS : Un café et une eau, s\'il vous plaît.\n\n'
   'SERVEUR : Parfait. Ça arrive tout de suite.')),
  ('Au Café de la Place (Partie 2)', (
   '(Le professeur arrive.)\n\n'
   'PROFESSEUR OKONKWO : Bonjour, Inès ! Bonjour, Marcus ! Comment allez-vous aujourd\'hui ?\n\n'
   'INÈS : Je vais très bien, merci, madame. Et vous ?\n\n'
   'PROFESSEUR OKONKWO : Je vais bien aussi, merci. Alors, vous êtes prêts pour l\'examen de vendredi ?\n\n'
   'MARCUS : Nous sommes un peu nerveux, mais nous étudions beaucoup.\n\n'
   'PROFESSEUR OKONKWO : C\'est bien. Vous avez des questions sur les verbes être et avoir ?\n\n'
   'INÈS : Oui ! J\'ai une question. Pourquoi dit-on "j\'ai faim" et pas "je suis faim" ?\n\n'
   'PROFESSEUR OKONKWO : Excellente question. En français, on utilise "avoir" pour la faim, la soif, et l\'âge — pas "être", comme en anglais. "J\'ai faim", "j\'ai soif", "j\'ai vingt ans."\n\n'
   'MARCUS : Ah, je comprends maintenant. Merci, madame.\n\n'
   'PROFESSEUR OKONKWO : De rien. Bon appétit, tous les deux ! On se voit vendredi.\n\n'
   'INÈS ET MARCUS : Merci, madame. À vendredi !'))],
 [('What explicit question does the server ask when Inès and Marcus arrive?', '"Vous êtes combien ?" (How many are you?)'),
  ('Translate Inès\'s response: "Nous sommes deux."', 'We are two. / There are two of us.'),
  ('Which verb (être or avoir) does Marcus use to explain he is hungry, and what is the exact phrase?', 'Avoir; "J\'ai très faim ce matin" (I am very hungry this morning).'),
  ('Why is "j\'ai faim" grammatically correct while a literal word-for-word translation using "être" would not be, according to the professor\'s explanation?', 'French uses avoir (to have) for expressions of hunger, thirst, and age, unlike English, which uses "to be"; the professor explicitly explains this as a fixed idiomatic pattern, not a free choice.'),
  ('Conjugate avoir for j\', tu, and vous, citing one example of each from the dialogue.', 'j\'ai (j\'ai faim), tu as (used implicitly with "toi, Marcus" context — accept correct form), vous avez (vous avez des questions) — all forms shown or implied in the dialogue.'),
  ('What does Inès order, and what article precedes each item?', 'Un café et une eau — "un" (masculine, café) and "une" (feminine, eau).'),
  ('Why does "café" take "un" and "eau" take "une"? Explain using grammatical gender.', 'Every French noun has a grammatical gender; café is masculine so it pairs with "un," and eau is feminine so it pairs with "une" — the article must agree with the noun\'s gender, not with logic about the object itself.'),
  ('What polite phrase does Marcus use when ordering, and what does it mean?', '"S\'il vous plaît," meaning "please" (formally, literally "if it pleases you").'),
  ('Identify one example of vouvoiement (formal "you") in Part 2, and explain why it is used instead of tutoiement.', 'The professor and students use "vous" with each other in most exchanges (e.g., "Comment allez-vous?"); vouvoiement is used because it reflects the respectful student-professor relationship, unlike the informal "tu" Inès and Marcus might use with each other.'),
  ('What question does Inès ask the professor about grammar, and how does the professor respond?', 'She asks why one says "j\'ai faim" instead of "je suis faim"; the professor explains that avoir, not être, is used for hunger, thirst, and age in French.'),
  ('Conjugate être for je, nous, and ils/elles, citing one dialogue example for at least one form.', 'je suis, nous sommes ("Nous sommes deux"), ils/elles sont — the nous and (implied) plural forms appear in the dialogue.'),
  ('What explicit feeling do Marcus and Inès express about the upcoming exam, and in what sentence?', 'They feel a little nervous: "Nous sommes un peu nerveux, mais nous étudions beaucoup."'),
  ('Identify the verb "étudier" in context and explain what conjugation pattern it likely follows.', '"Nous étudions" (we study) follows the regular -er verb pattern, similar to parler: étudier → j\'étudie, nous étudions, etc.'),
  ('Translate the professor\'s closing line: "On se voit vendredi."', 'We\'ll see each other Friday. / See you Friday.'),
  ('Write a two-line greeting exchange between a student and a café server, using vous.', 'Answers vary; must use formal "vous" and an accurate greeting-response pattern, e.g., "Bonjour, vous êtes combien?" / "Bonjour, nous sommes trois."'),
  ('Write a short French sentence ordering a drink and a food item, using "je voudrais."', 'Answers vary; must use "je voudrais" plus correctly gendered articles, e.g., "Je voudrais un chocolat chaud et une baguette."'),
  ('Explain, in English, the difference between "un/une" and "le/la" as used in this dialogue.', '"Un/une" are indefinite articles (a/an), used for ordering an unspecified item, like "un café"; "le/la" are definite articles (the), used for a specific, already-known item — the dialogue uses indefinite articles because the items are being requested for the first time.'),
  ('Rewrite "Je voudrais un thé" using "avoir envie de" (to feel like/want) instead of "voudrais."', 'J\'ai envie d\'un thé. (Note the elision of "de" to "d\'" before a vowel.)'),
  ('Why might a French instructor consider this dialogue useful for practicing both être and avoir in the same scene?', 'Because it embeds both verbs in natural, connected contexts — being polite and describing feelings (avoir faim, être nerveux) — rather than presenting them as isolated conjugation drills, helping students internalize real usage patterns.'),
  ('Write a full four-line dialogue exchange, in French, ordering a meal and responding to "Comment allez-vous?"', 'Answers vary; must include a greeting, a response to "Comment allez-vous?", a food/drink order using "je voudrais" or "j\'ai envie de," and a polite closing.')],
 '90-minute session',
 800,
 vocab=[
   ('bienvenue', 'welcome'), ('vous êtes combien ?', 'how many are you? (party size)'),
   ('rendez-vous', 'appointment / meeting'), ('je voudrais', 'I would like'),
   ('avoir faim / avoir soif', 'to be hungry / to be thirsty (literally, "to have hunger/thirst")'),
   ('comment allez-vous ?', 'how are you? (formal)'), ('nerveux / nerveuse', 'nervous'),
   ('de rien', 'you\'re welcome'),
 ],
 pacing='Warm-up 8 min · dialogue read-aloud + vocabulary 15 min · guided grammar organizer 20 min · partner role-play 15 min · independent practice 20 min · extension work 8 min · assessment 4 min.')

# ---------------------------------------------------------------- German 101
add('german101-introductions', 'German 101: Erste Woche an der Uni — A Full Introductions Session', 'German 101', 'German',
 'COURSE-OBJ.DE101.2',
 'Introduce yourself and exchange basic personal information using greetings, pronouns, sein, heißen, and regular present-tense verbs.',
 'Use beginner German accurately to greet others, introduce yourself, ask and answer questions about origin, and describe simple daily activities.',
 'Sein (to be) is irregular and essential to identity statements (ich bin, du bist, er/sie/es ist). Heißen (to be named) and kommen (to come) are regular weak verbs following the -e, -st, -t, -en, -t, -en pattern. German distinguishes formal Sie from informal du, and questions without a question word (yes/no questions) are formed by inverting the verb and subject.',
 [('Conjugate heißen for ich, du, and wir.', 'ich heiße, du heißt, wir heißen — regular weak-verb pattern with a spelling adjustment (ß after the stem vowel).'),
  ('Why does German use "Sie" instead of "du" when a student first meets a new professor?', 'Sie is the formal form of "you," used with strangers, professors, and in professional contexts to show respect, while "du" is reserved for friends, family, and peers.')],
 [('Erste Woche an der Uni (Teil 1)', (
   'PROFESSOR BRAUN : Guten Morgen! Willkommen zum ersten Deutschkurs. Ich heiße Professor Braun. Und wie heißen Sie?\n\n'
   'LEONIDAS : Guten Morgen, Professor Braun. Ich heiße Leonidas. Ich komme aus Griechenland.\n\n'
   'PROFESSOR BRAUN : Sehr schön! Und woher kommst du — äh, entschuldigung, woher kommen Sie?\n\n'
   'NAOMI : Ich heiße Naomi. Ich komme aus Kanada, aber meine Familie kommt aus Nigeria.\n\n'
   'PROFESSOR BRAUN : Interessant! Sprechen Sie schon ein bisschen Deutsch, Naomi?\n\n'
   'NAOMI : Ein bisschen. Ich lerne seit zwei Jahren Deutsch in der Schule.\n\n'
   'PROFESSOR BRAUN : Ausgezeichnet. Und Sie, Leonidas — sprechen Sie andere Sprachen?\n\n'
   'LEONIDAS : Ja, ich spreche Griechisch, Englisch, und ein bisschen Spanisch.\n\n'
   'PROFESSOR BRAUN : Wunderbar. In diesem Kurs lernen wir zusammen. Sind Sie bereit?\n\n'
   'LEONIDAS UND NAOMI : Ja, wir sind bereit!')),
  ('Erste Woche an der Uni (Teil 2)', (
   '(Nach dem Unterricht sprechen Leonidas und Naomi miteinander.)\n\n'
   'LEONIDAS : Hallo Naomi! Wie geht es dir?\n\n'
   'NAOMI : Mir geht es gut, danke! Und dir?\n\n'
   'LEONIDAS : Auch gut, danke. Du sprichst wirklich gut Deutsch für eine Anfängerin!\n\n'
   'NAOMI : Danke schön! Aber ich mache noch viele Fehler. Zum Beispiel, ich vergesse oft die Artikel — der, die, das.\n\n'
   'LEONIDAS : Ich auch! Das ist wirklich schwer. Lernst du jeden Tag?\n\n'
   'NAOMI : Ja, ich lerne jeden Abend eine halbe Stunde. Und du?\n\n'
   'LEONIDAS : Ich lerne meistens am Wochenende, aber vielleicht sollte ich das ändern.\n\n'
   'NAOMI : Wir könnten zusammen lernen! Das hilft oft mehr als allein lernen.\n\n'
   'LEONIDAS : Gute Idee! Bis morgen dann, Naomi.\n\n'
   'NAOMI : Bis morgen! Tschüss!'))],
 [('What explicit question does Professor Braun ask when introducing the class, and to whom first?', '"Und wie heißen Sie?" (And what is your name?), asked to Leonidas.'),
  ('What mistake does Professor Braun make and immediately correct in Part 1? What does this reveal about du vs. Sie?', 'The professor starts to say "kommst du" (informal) then corrects to "kommen Sie" (formal), showing that even native speakers can slip, but the formal register is expected between a professor and new students.'),
  ('Where is Leonidas from, and what languages does he say he speaks?', 'He is from Greece (Griechenland); he speaks Greek, English, and a little Spanish.'),
  ('Where is Naomi from, and what additional detail does she give about her family?', 'She is from Canada, but her family comes from Nigeria — showing origin and family heritage can differ.'),
  ('Conjugate kommen for ich, sie (she), and wir, citing at least one example from the dialogue.', 'ich komme ("Ich komme aus Griechenland"), sie kommt ("meine Familie kommt aus Nigeria" — third person singular), wir kommen — regular weak-verb pattern.'),
  ('How long has Naomi been learning German, and what explicit phrase does she use to say so?', 'Two years; "Ich lerne seit zwei Jahren Deutsch in der Schule."'),
  ('What grammatical structure does "seit zwei Jahren" (for two years) illustrate about German time expressions?', 'German uses "seit" (since/for) with a time period to describe an action that started in the past and continues into the present, similar to English "I have been learning for two years."'),
  ('In Part 2, what informal greeting do Leonidas and Naomi use with each other, and how does it differ from Part 1\'s greetings?', 'They use "du" (informal "you"): "Wie geht es dir?" instead of the formal "Sie" used with Professor Braun, reflecting their peer relationship.'),
  ('What specific mistake does Naomi say she often makes, and why is this mistake understandable for a beginner?', 'She often forgets the articles der, die, das; this is understandable because German nouns have three genders that must be memorized individually, unlike English, which has only "the."'),
  ('What study habit does Naomi describe, and how does it differ from Leonidas\'s habit?', 'Naomi studies every evening for half an hour; Leonidas mostly studies on weekends — Naomi\'s practice is more frequent and consistent.'),
  ('What suggestion does Naomi make at the end of Part 2, and why might this be effective for language learning?', 'She suggests they study together; studying together can provide practice speaking aloud, mutual correction, and accountability, all useful for language acquisition.'),
  ('Translate: "Ich lerne seit zwei Jahren Deutsch."', 'I have been learning German for two years.'),
  ('Write a two-line formal introduction using Sie, following the pattern in Part 1.', 'Answers vary; must use "Sie" correctly, e.g., "Guten Tag, wie heißen Sie?" / "Ich heiße [name]. Ich komme aus [place]."'),
  ('Write a two-line informal exchange using du, asking and answering "How are you?"', 'Answers vary; must use "du" correctly, e.g., "Wie geht es dir?" / "Mir geht es gut, danke."'),
  ('Explain, in English, the difference between "ich heiße" and "ich bin" when introducing yourself.', '"Ich heiße" specifically means "I am called/named," used for stating one\'s name, while "ich bin" (I am) is more general and can be followed by other descriptions, like a profession or nationality — both can introduce oneself but "heißen" is specific to naming.'),
  ('Rewrite Leonidas\'s line "Ich spreche Griechisch, Englisch, und ein bisschen Spanisch" using "auch" (also) to add a fourth language of your choice.', 'Answers vary; must correctly place "auch," e.g., "Ich spreche auch ein bisschen Französisch."'),
  ('Why might this two-part dialogue (formal classroom introduction, then informal peer conversation) be useful for practicing register in German?', 'It lets students see the same two characters use different pronouns and tone depending on their relationship with the listener, making the formal/informal distinction concrete rather than abstract.'),
  ('Identify one cognate (word that looks similar in English and German) in the dialogue and explain how recognizing cognates can help beginners.', 'Answers vary; e.g., "Familie" (family) or "Idee" (idea) — recognizing cognates can help beginners guess meaning quickly and build vocabulary confidence before full grammar mastery.'),
  ('Write a full four-line dialogue, in German, in which two students meet for the first time and exchange names, origins, and a closing.', 'Answers vary; must include a greeting, a name exchange using heißen, an origin statement using kommen aus, and an appropriate closing (formal or informal, but consistent).'),
  ('Explain why "sprechen" changes its stem vowel in the du and er/sie/es forms (du sprichst, er spricht) but not in the wir or Sie forms.', 'Sprechen is a strong verb with a stem-vowel change (e→i) in the second- and third-person singular only; this irregular pattern must be memorized, unlike the fully regular weak-verb conjugations of heißen or kommen.')],
 '90-minute session',
 800,
 vocab=[
   ('willkommen', 'welcome'), ('woher kommen Sie / kommst du?', 'where are you from? (formal/informal)'),
   ('ein bisschen', 'a little bit'), ('seit zwei Jahren', 'for two years'),
   ('wie geht es dir/Ihnen?', 'how are you? (informal/formal)'), ('Anfängerin / Anfänger', 'beginner (f./m.)'),
   ('vielleicht', 'maybe'), ('zusammen lernen', 'to study together'),
 ],
 pacing='Warm-up 8 min · dialogue read-aloud + vocabulary 15 min · guided grammar organizer 20 min · partner role-play 15 min · independent practice 20 min · extension work 8 min · assessment 4 min.')

# -------------------------------------------------------------- Mandarin 101
add('mandarin101-campus', 'Mandarin 101: 在校园里 — A Full Campus Introductions Session', 'Mandarin 101', 'Mandarin Chinese',
 'COURSE-OBJ.ZH101.2',
 'Exchange greetings, personal information, and campus-related requests using correct tone, the verbs 是 and 叫, and 吗 / verb-not-verb question patterns.',
 'Use beginner Mandarin accurately to greet others, introduce yourself, state nationality and current activity, and ask simple yes/no questions about campus life.',
 'Mandarin identity and naming: 是 (shì, "to be/equals") links a subject to a category or identity noun (我是学生), while 叫 (jiào, "to be called") is used specifically to state a name (我叫大卫). Neither verb changes form for person, number, or tense — Mandarin is an analytic language, so meaning depends on word order, particles (吗, 呢, 吧), and tone rather than conjugation or agreement. Yes/no questions are formed either by adding the particle 吗 to a statement or by repeating the verb in a positive-then-negative pattern (verb-not-verb, e.g., 饿不饿).',
 [('Stating identity/category with 是', '我是学生。(Wǒ shì xuéshēng.) "I am a student." 是 links a subject to a noun of identity or category and never changes form for person or tense; time and number are shown by separate words (e.g., 昨天, 明天) rather than verb endings.'),
  ('Asking yes/no questions two ways', '你是老师吗?(Nǐ shì lǎoshī ma?) or 你是不是老师?(Nǐ shì bu shì lǎoshī?) — both mean "Are you a teacher?" Adding 吗 to a statement, or repeating the verb in positive-then-negative form, are the two standard ways to form a yes/no question without otherwise changing word order.')],
 [('在校园里 · 第一天上课 (Zài xiàoyuán lǐ · Dì yī tiān shàngkè) — On Campus, Part 1: First Day of Class', (
   '王老师 (Wáng lǎoshī): 大家好!欢迎来上中文课。我姓王,你们可以叫我王老师。 (Dàjiā hǎo! Huānyíng lái shàng Zhōngwén kè. Wǒ xìng Wáng, nǐmen kěyǐ jiào wǒ Wáng lǎoshī.)\n\n'
   '大卫 (Dàwèi): 老师好!我叫大卫。很高兴认识您。 (Lǎoshī hǎo! Wǒ jiào Dàwèi. Hěn gāoxìng rènshi nín.)\n\n'
   '王老师: 很高兴认识你,大卫。你是哪国人? (Hěn gāoxìng rènshi nǐ, Dàwèi. Nǐ shì nǎ guó rén?)\n\n'
   '大卫: 我是美国人。我从芝加哥来。 (Wǒ shì Měiguó rén. Wǒ cóng Zhījiāgē lái.)\n\n'
   '王老师: 太好了。那你呢,美丽? (Tài hǎo le. Nà nǐ ne, Měilì?)\n\n'
   '美丽 (Měilì): 老师好,我叫陈美丽。我是中国人,可是我在这个大学学习法语。 (Lǎoshī hǎo, wǒ jiào Chén Měilì. Wǒ shì Zhōngguó rén, kěshì wǒ zài zhège dàxué xuéxí Fǎyǔ.)\n\n'
   '王老师: 有意思!你会说中文和法语,真棒。好,我们开始上课吧。 (Yǒuyìsi! Nǐ huì shuō Zhōngwén hé Fǎyǔ, zhēn bàng. Hǎo, wǒmen kāishǐ shàngkè ba.)')),
  ('在校园里 · 下课以后 (Xiàkè yǐhòu) — On Campus, Part 2: After Class', (
   '大卫: 美丽,下课以后你要去哪儿? (Měilì, xiàkè yǐhòu nǐ yào qù nǎr?)\n\n'
   '美丽: 我要去图书馆看书。你呢? (Wǒ yào qù túshūguǎn kàn shū. Nǐ ne?)\n\n'
   '大卫: 我要去学生食堂吃饭。我很饿。 (Wǒ yào qù xuésheng shítáng chī fàn. Wǒ hěn è.)\n\n'
   '美丽: 食堂的中国菜很好吃。你想不想试一试? (Shítáng de Zhōngguó cài hěn hǎochī. Nǐ xiǎng bu xiǎng shì yi shì?)\n\n'
   '大卫: 好啊!我们一起去吧。你饿不饿? (Hǎo a! Wǒmen yìqǐ qù ba. Nǐ è bu è?)\n\n'
   '美丽: 有一点儿饿。走吧! (Yǒu yìdiǎnr è. Zǒu ba!)\n\n'
   '大卫: 这个菜真好吃!谢谢你,美丽。 (Zhège cài zhēn hǎochī! Xièxie nǐ, Měilì.)\n\n'
   '美丽: 不客气。明天见! (Bú kèqi. Míngtiān jiàn!)'))],
 [('Use the pattern with 叫 to write a sentence stating your own name, giving the pinyin.', 'Answers vary; must use 叫 correctly, e.g., 我叫 Alex。(Wǒ jiào Alex.) 叫 is invariant — it never changes form regardless of who is speaking.'),
  ('Why is there no conjugation needed to change 是 for "I am," "you are," or "she is" in Mandarin, unlike French être or German sein?', 'Mandarin verbs do not change form for person or number — 是 (shì) stays exactly the same whether the subject is 我 (I), 你 (you), or 她 (she); grammatical relationships are shown by word order and particles, not verb endings.'),
  ('What Chinese phrase does 王老师 use to welcome the class, and what does it mean?', '"大家好!欢迎来上中文课。" (Dàjiā hǎo! Huānyíng lái shàng Zhōngwén kè.) = "Hello everyone! Welcome to Chinese class."'),
  ('What question does 王老师 ask David to find out his nationality, and what is the literal meaning of the words?', '"你是哪国人?" (Nǐ shì nǎ guó rén?), literally "you are which country person?" = "What is your nationality?"'),
  ('Explain how "哪国人" combines "which," "country," and "person" into a single question phrase, and how this differs from English word order.', '哪 (which) + 国 (country) + 人 (person) stack directly with no preposition, unlike English "What country are you from?"; Mandarin regularly builds phrases this way, letting word order alone carry meaning.'),
  ('Translate Meili\'s response explaining she is Chinese but studies French: "我是中国人,可是我在这个大学学习法语。"', '"I am Chinese, but I study French at this university."'),
  ('Discuss with a partner: why might David introduce himself with "很高兴认识您" (using 您) to the teacher, but Meili and David would likely use 你 with each other?', '您 is the polite/formal form of "you," appropriate for addressing a teacher or elder; 你 is the standard informal form used between peers — similar to the vous/tu distinction in French or Sie/du in German.'),
  ('With a partner, practice asking "你饿不饿?" (are you hungry or not?) and answering truthfully. Explain the grammar pattern used.', 'This is the "verb-not-verb" (positive-negative) question pattern (饿不饿), a common way to ask a yes/no question in Mandarin without needing the particle 吗.'),
  ('Discuss what 王老师\'s comment "你会说中文和法语,真棒" reveals about Meili, and translate it.', '"You can speak Chinese and French, that\'s really great." It shows the class values multilingualism, and that being a native Chinese speaker doesn\'t exempt Meili from also being a language learner (of French).'),
  ('Where does David say he is from, and what is the pinyin for the city name?', '芝加哥 (Zhījiāgē) — Chicago.'),
  ('What does David want to do after class, and where?', '去学生食堂吃饭 (qù xuésheng shítáng chī fàn) — go to the student cafeteria to eat.'),
  ('What does Meili want to do after class, and where?', '去图书馆看书 (qù túshūguǎn kàn shū) — go to the library to read/study.'),
  ('Translate Meili\'s line: "食堂的中国菜很好吃。你想不想试一试?"', '"The cafeteria\'s Chinese food is very delicious. Do you want to try it?"'),
  ('Identify the particle 吧 in "我们一起去吧" and explain its function.', '吧 softens a statement into a suggestion, similar to "let\'s..." in English; "我们一起去吧" = "Let\'s go together."'),
  ('What does David say to thank Meili at the end, and how does she respond?', '"谢谢你,美丽" (Xièxie nǐ, Měilì) — "Thank you, Meili"; she responds "不客气" (Bú kèqi) — "You\'re welcome."'),
  ('Write a short exchange using 吗 to ask a yes/no question and answer it, based on the pattern in the dialogue.', 'Answers vary; must use 吗 correctly, e.g., "你是老师吗?" / "不是,我是学生。"'),
  ('Rewrite "你饿不饿?" using 吗 instead of the verb-not-verb pattern, and explain if the meaning changes.', '"你饿吗?" — the meaning is the same (Are you hungry?); 吗 and verb-not-verb are two equally common ways to form yes/no questions, interchangeable in most contexts.'),
  ('Explain why Mandarin relies on tone rather than verb conjugation or gendered articles to distinguish meaning, and give one tone-pair example from the vocabulary or dialogue.', 'Mandarin is a tonal, analytic language: each syllable carries a pitch contour that changes its meaning entirely (e.g., 妈 mā "mother" vs. 骂 mà "to scold"), while grammatical relationships come from word order and particles rather than word endings — unlike French or German, no noun-adjective agreement or verb conjugation is needed.'),
  ('Compare "我是学生" (I am a student) and "我叫大卫" (I am called David) using the 是 vs. 叫 explanation, then write one additional original sentence using each verb correctly.', 'Answers vary; must show 是 used for identity/category and 叫 used for naming, e.g., "我是老师。" / "我叫王美丽。"'),
  ('Write a short four-line original dialogue in Mandarin (with pinyin) in which two students meet for the first time, exchange names using 叫, ask where each other is from using 哪, and close politely.', 'Answers vary; must include a greeting, a name exchange using 叫, an origin question/answer using 哪 or 哪国, and a polite closing (e.g., 再见 or 明天见).')],
 '90-minute session',
 800,
 vocab=[
   ('你好 / 大家好', 'nǐ hǎo / dàjiā hǎo — hello / hello everyone'),
   ('欢迎', 'huānyíng — welcome'),
   ('很高兴认识你/您', 'hěn gāoxìng rènshi nǐ/nín — nice to meet you (informal/formal)'),
   ('哪国人', 'nǎ guó rén — what nationality (literally "which country person")'),
   ('可是', 'kěshì — but, however'),
   ('食堂', 'shítáng — cafeteria'),
   ('好吃', 'hǎochī — delicious'),
   ('不客气', 'bú kèqi — you\'re welcome'),
 ],
 pacing='Warm-up 8 min · dialogue read-aloud + vocabulary 15 min · guided grammar organizer 20 min · partner role-play 15 min · independent practice 20 min · extension work 8 min · assessment 4 min.',
 text_font='CJK')

# ------------------------------------------------------------------- ASL 101
add('asl101-classroom', 'ASL 101: Classroom Communication and Fingerspelling — A Full Practice Session', 'ASL 101', 'American Sign Language',
 'COURSE-OBJ.ASL101.2',
 'Apply visual-attention etiquette, fingerspell names and unfamiliar terms at a readable pace, and produce beginner greetings and questions with the correct nonmanual signals.',
 'Use beginner ASL etiquette and vocabulary accurately to get attention respectfully, fingerspell names, and ask and answer yes/no and WH-questions with correct facial grammar.',
 'ASL is a full, independent visual-gestural language with its own grammar, not a signed version of English. Meaning comes from handshape, movement, and location together with nonmanual signals (NMS) — facial expressions and head/body posture that function as grammar, not just emotion. A yes/no question is marked by raised eyebrows and a forward head tilt; a WH-question (who, what, where, when, why, how) is marked by furrowed/lowered eyebrows. Fingerspelling is used mainly for names, places, or terms with no established sign, and should flow smoothly rather than being punched out letter by letter. Every exchange depends on shared eye gaze, so getting someone\'s attention respectfully — a light tap, a wave in their sightline, or a light flick with permission — replaces calling out a name.',
 [('Getting attention respectfully', 'Never grab an arm or wave wildly. Instead: wave once in the person\'s peripheral vision, tap the shoulder lightly once, or flick the room light with permission — then wait for full eye contact before beginning.'),
  ('Marking a yes/no question vs. a WH-question', '"Are you a student?" uses raised eyebrows and a forward tilt. "Where do you study?" uses lowered, furrowed eyebrows instead. The handshapes stay the same; only the nonmanual signal marks the question type.')],
 [('Before You Sign: Setting Up a Respectful Exchange', (
   'Good ASL communication starts before the first sign. A signer chooses a position with clear sightlines: no bright window or lamp directly behind them, since strong backlighting turns hands and face into a dark silhouette that is hard to read. Seating in a small circle or a loose semicircle, rather than in rows, lets every participant see every other participant\'s hands and face at once — in a spoken classroom, facing forward is normal; in a signing classroom, facing forward can mean facing away from half the conversation.\n\n'
   'Attention-getting is a visible, deliberate step, not an interruption to apologize for. A signer who wants to begin a conversation checks whether the other person\'s eyes are already free. If not, they wait for a natural break, then use one clear, controlled method: a single wave inside the other person\'s peripheral vision, a light single tap on the shoulder or table near the person, or, in a full classroom, the instructor briefly flicking the light switch. Grabbing an arm, waving repeatedly and rapidly, or shouting a name are all considered intrusive — they treat a Deaf or signing space as if it worked like a hearing one.\n\n'
   'Once eye contact is established, it is held for the length of the exchange, not just the greeting. Looking away mid-sentence in ASL is closer to trailing off mid-word in speech: it can signal the turn is being given up. A signer who needs to glance away briefly — to check a phone, for example — should complete their sentence, break eye contact clearly, and then re-establish it before continuing, so their conversation partner is not left guessing whether the exchange is still active.')),
  ('A Beginner Classroom Exchange, Described', (
   'Jamal turns to face Priya directly, positioning himself so the classroom window is behind him rather than behind her, keeping his hands and face clearly lit for her. He waits until her eyes are already on him — she has just finished writing something down and looks up — before he moves. He gives a single, controlled wave at chest height inside her sightline. Priya\'s eyes come to him immediately and stay there.\n\n'
   'Jamal signs a standard greeting, then brings both hands up to fingerspell his name: J-A-M-A-L, produced smoothly, each handshape flowing into the next at a steady, readable rhythm rather than being punched out letter by letter. He follows it with the sign for NAME and a questioning point back toward Priya, his eyebrows raised and his head tilted slightly forward — the nonmanual marker that turns the gesture into a yes/no-style prompt: "And you?"\n\n'
   'Priya fingerspells P-R-I-Y-A at a matching pace, then signs STUDENT and points to herself. She lowers and furrows her eyebrows as she signs WHERE, tilting forward — the WH-question marker — asking Jamal where he studies. He answers, naming his program, then mirrors the question back to her with the same WH-question expression. Neither of them looks away mid-question; the eye contact and the facial grammar carry as much of the exchange as the handshapes do.\n\n'
   'At the end, Jamal signs THANK-YOU and a closing sign, breaking eye contact only after Priya has clearly signed a closing response back — a visible, mutual signal that the exchange, not just the sentence, is finished.'))],
 [('What two attention-getting methods does the lesson approve of, and which does it explicitly reject?', 'Approved: a single controlled wave in the other person\'s sightline, or a light single tap on the shoulder (or, in a group, a brief light flick with permission). Rejected: grabbing an arm, waving repeatedly/wildly, or shouting a name.'),
  ('Why does the lesson say a signer should avoid sitting with a bright window directly behind them?', 'Strong backlighting turns the signer\'s hands and face into a dark silhouette, making handshape, movement, and facial grammar hard for the other person to read.'),
  ('In the described exchange, what does Jamal do with his body/position before signing anything, and why?', 'He positions himself so the window light is behind him, not behind Priya, keeping his own hands and face well-lit for her to read — and he waits for her eyes before beginning.'),
  ('What nonmanual signal does Jamal use when asking "And you?" after introducing himself, and what does it mark?', 'Raised eyebrows with a forward head tilt, marking it as a yes/no-style question.'),
  ('What nonmanual signal does Priya use when asking where Jamal studies, and how does it differ from the previous one?', 'Lowered/furrowed eyebrows with a forward head tilt — the WH-question marker — which differs from the raised-eyebrow yes/no marker used earlier.'),
  ('Explain, using the lesson\'s own wording, why ASL is not "a signed version of English."', 'ASL is described as a full, independent visual-gestural language with its own grammar; meaning comes from handshape, movement, location, and nonmanual signals together, not from mapping English words one-to-one onto signs.'),
  ('Discuss with a partner: why might looking away mid-sentence in ASL cause confusion, based on the passage\'s comparison to speech?', 'The passage compares it to trailing off mid-word — looking away mid-sentence can signal the turn is being given up, so a partner may not know whether the conversation is still active, causing an awkward or confusing pause.'),
  ('With a partner, practice the attention-getting sequence described (wait for a break, use one clear method, wait for eye contact) and explain out loud why each step matters.', 'Answers vary; must correctly sequence: wait for a natural break, use a single controlled attention-getter, then wait for full eye contact before beginning to sign.'),
  ('Discuss: why does the lesson recommend a semicircle seating arrangement instead of rows for a signing classroom?', 'Rows work for a spoken classroom where facing forward is enough, but in a signing classroom facing forward can mean facing away from other participants; a semicircle lets everyone see everyone else\'s hands and face at once.'),
  ('How does Jamal fingerspell his name, according to the passage, and what is the recommended rhythm for fingerspelling in general?', 'He fingerspells J-A-M-A-L smoothly, each handshape flowing into the next at a steady, readable rhythm — not punched out letter by letter.'),
  ('What is fingerspelling mainly used for, according to the lesson?', 'Proper names, places, or terms that have no established sign.'),
  ('What does the passage say happens if a signer needs to glance away mid-conversation (for example, to check a phone)?', 'They should complete their sentence, break eye contact clearly, and then re-establish it before continuing, so their partner is not left guessing whether the exchange is still active.'),
  ('What visible, mutual signal ends the exchange between Jamal and Priya, according to the passage?', 'Jamal signs THANK-YOU and a closing sign, and only breaks eye contact after Priya has clearly signed a closing response back.'),
  ('Explain what "gloss" is and why the lesson calls it "not ASL itself."', 'Gloss is a limited written notation (ALL CAPS English words) used to discuss or record signs on paper; it is not ASL itself because it cannot capture handshape, movement, location, or nonmanual grammar — it is only a reference tool.'),
  ('Write a short plan (3-4 steps) for how you would respectfully get a classmate\'s attention across a room, using the etiquette described in the lesson.', 'Answers vary; must include waiting for a natural break, choosing one non-intrusive method appropriate to the distance (e.g., moving into sightline and waving once, or asking someone closer to relay), and waiting for eye contact before beginning.'),
  ('A beginner fingerspells a name by pausing heavily between every letter. Using the lesson\'s guidance, explain what to correct and why.', 'The lesson recommends a smooth, steady, readable rhythm with letters flowing into each other; heavy pauses between every letter make the word harder to read as a whole rather than easier, and go against the described best practice.'),
  ('Explain why eye gaze is described as carrying "as much of the exchange as the handshapes do." What would be lost if eye contact broke during a question?', 'Because nonmanual signals (like eyebrow position) are produced with the face while eye gaze maintains the visual channel itself; breaking eye contact could mean missing the nonmanual grammar that distinguishes a yes/no question from a WH-question, or signal that the turn has ended.'),
  ('Compare the classroom-seating reasoning in this lesson to a hearing classroom you have experienced. What is one accommodation a hearing classroom would need to add to be signing-friendly?', 'Answers vary; must identify a specific accommodation (e.g., semicircular seating, controlled/non-backlit lighting, sightline-clear sightlines to an interpreter or the instructor) and connect it to a specific point made in the lesson.'),
  ('Write a short original description (4-6 sentences, in the same descriptive style as the passage) of a beginner signer asking a classmate a WH-question and receiving an answer, correctly noting the nonmanual signal used.', 'Answers vary; must describe a WH-question with the correct nonmanual signal (furrowed/lowered eyebrows, forward head tilt) named explicitly, distinct from a yes/no question.'),
  ('Self-assessment: describe one specific etiquette or grammar point from today\'s lesson you feel confident about, and one you still need to practice.', 'Answers vary; must name a specific point from the lesson (e.g., attention-getting method, fingerspelling rhythm, yes/no vs. WH-question marker) for each part.')],
 '90-minute session',
 800,
 vocab=[
   ('eye gaze', 'visual contact that holds a turn and carries grammar'),
   ('fingerspelling', 'spelling a word with the manual alphabet'),
   ('nonmanual signal (NMS)', 'facial/head grammar, e.g. raised eyebrows'),
   ('sign space', 'the area used to produce and reference signs'),
   ('gloss', 'ALL CAPS notation for signs; not ASL itself'),
   ('WH- vs. YES/NO marker', 'furrowed brow (WH-) vs. raised brow (yes/no)'),
 ],
 pacing='Warm-up 8 min · guided reading of both passages + vocabulary 18 min · guided etiquette/grammar organizer 18 min · partner practice of described exchanges 18 min · independent practice 18 min · extension work 6 min · assessment 4 min.')

# ----------------------------------------------------------- Art Appreciation
add('art-composition', 'Art Appreciation 101: The Composition Detective — A Full Analysis Session', 'Art Appreciation', 'Fine Arts',
 'COURSE-OBJ.ART101.2',
 'Analyze how line, shape, color, value, contrast, space, emphasis, and balance work together to create calm or tension in an original composition, using precise formal-analysis vocabulary.',
 'Use precise art vocabulary to analyze and justify claims about how the formal elements of two original abstract compositions create meaning and mood.',
 'Formal analysis describes what is visually present — line, shape, color, value, texture, space — and how those elements are organized using principles such as balance, emphasis, contrast, and unity. Symmetrical balance mirrors visual weight across an axis and tends to read as calm or stable; asymmetrical balance uses unequal elements that still achieve equilibrium, and often reads as more dynamic or tense. Emphasis is created by a strong contrast — in color, size, value, or shape — that isolates one area as a focal point. Two original studies are printed below: Study A, built from evenly spaced, low-contrast horizontal bands and a centered axis, and Study B, built from uneven diagonal bars, a small high-contrast circle, and an off-center block.',
 [('Reading symmetrical balance in Study A', 'The three bands in Study A are evenly spaced and sit in a narrow, related value range (all cool, muted tones); a thin centered vertical line marks an axis that the bands echo above and below. Even spacing plus low value contrast plus a visible axis are the three formal choices that read as calm.'),
  ('Reading emphasis and asymmetry in Study B', 'The small gold circle in Study B is the highest-contrast, highest-saturation shape on the page, placed off-center rather than in the middle — that combination of contrast, saturation, and off-center placement is what makes the eye land on it first, even though the dark diagonal bars and the large block occupy more total area.')],
 [('Study A — Original Composition (Balance and Calm)', 'Formal elements to identify: three horizontal bands, even spacing, a centered vertical axis, and a narrow, low-contrast value range. Study the composition below before answering the guided and independent questions.'),
  ('Study B — Original Composition (Emphasis and Tension)', 'Formal elements to identify: uneven diagonal bars, an off-center high-contrast circle, and one large asymmetrical block. Study the composition below and compare it directly to Study A.')],
 [('Define emphasis in your own words, then name the element in Study B that creates it.', 'Emphasis is a focal area given greater visual attention through contrast; in Study B, the small gold circle creates emphasis because of its high contrast and saturation against the darker diagonal bars.'),
  ('Define balance, then state which type (symmetrical or asymmetrical) Study A uses and how you know.', 'Balance is the distribution of visual weight across a composition. Study A uses symmetrical balance: the three bands are evenly spaced around a centered vertical axis, mirroring visual weight above and below/around that axis.'),
  ('Identify the value range used in Study A (wide or narrow) and explain what effect it has.', 'Study A uses a narrow value range (the bands are all similar, muted, cool tones); a narrow range lowers contrast, which reduces visual tension and contributes to a calm reading.'),
  ('Compare the spacing of elements in Study A to the spacing in Study B. What does each spacing choice communicate?', 'Study A uses even, regular spacing between the three bands, communicating order and predictability; Study B uses uneven spacing between the diagonal bars, communicating irregularity and energy.'),
  ('Explain, using evidence from both studies, why "more area" does not always mean "more emphasis."', 'In Study B, the dark diagonal bars and the large block cover more total area than the small gold circle, but the circle still draws the eye first because of its contrast and saturation — emphasis depends on visual difference from its surroundings, not on physical size alone.'),
  ('Identify the axis in Study A and explain what "symmetrical balance" means using that axis as evidence.', 'The centered vertical line is the axis; symmetrical balance means visual weight is distributed evenly on either side of (or around) that axis, which is visible in how the three bands relate to the centered line.'),
  ('With a partner, each choose one study and describe it aloud using at least three formal-analysis terms from today\'s vocabulary, without saying "I like it" or "it looks nice."', 'Answers vary; must use at least three formal terms (e.g., emphasis, balance, contrast, value, axis) to describe visible elements rather than a personal preference statement.'),
  ('Discuss with a partner: if you swapped the gold circle in Study B for a muted gray circle, what would likely change, and why?', 'The emphasis would weaken or disappear, because emphasis in Study B depends on the circle\'s high contrast and saturation relative to its surroundings; a muted gray circle would blend into the value range of the rest of the composition.'),
  ('Discuss: which study would you choose as a "calm" waiting-room piece and which as an "energizing" entryway piece? Justify each choice using formal-analysis vocabulary, not personal taste.', 'Study A for the waiting room (symmetrical balance, narrow value range, even spacing create calm); Study B for the entryway (asymmetry, high contrast, and diagonal energy create dynamism) — justification must cite formal elements, not preference.'),
  ('Write a three-sentence formal analysis of Study A that names at least two elements and one principle of organization.', 'Answers vary; must name at least two elements (e.g., value, line, shape) and one organizing principle (e.g., balance) and describe their visible effect, not a subjective opinion.'),
  ('Write a three-sentence formal analysis of Study B that names at least two elements and one principle of organization.', 'Answers vary; must name at least two elements (e.g., color, contrast, shape) and one organizing principle (e.g., emphasis or asymmetry) and describe their visible effect.'),
  ('Distinguish observation from interpretation, then write one observation and one interpretation about Study B.', 'Observation states a visible fact (e.g., "the circle is gold and small"); interpretation explains a possible meaning or effect (e.g., "the circle feels like a spark of energy against the darker bars"). One clear example of each is required.'),
  ('Revise, in writing, how you would change Study B to make it feel calmer without removing any shapes — only describe changes to color, value, or spacing.', 'Answers vary; must propose specific changes (e.g., narrowing the value range, evening out the spacing between bars, reducing the circle\'s saturation) tied to a calming effect.'),
  ('Explain how repeated diagonal lines in Study B affect the viewer\'s eye movement compared to the horizontal bands in Study A.', 'Diagonal lines suggest movement and instability, pulling the eye along an angled path, while horizontal bands suggest stability and rest, letting the eye move calmly left to right — this is a common effect of line direction in formal analysis.'),
  ('Choose two elements from today\'s vocabulary and explain how they work together (not separately) in Study A to create its overall effect.', 'Answers vary; must explain an interaction, e.g., "narrow value range and even spacing work together — without the even spacing, the narrow value range alone might feel flat rather than calm."'),
  ('Choose two elements from today\'s vocabulary and explain how they work together in Study B.', 'Answers vary; must explain an interaction, e.g., "contrast and off-center placement work together — the contrast alone would not create emphasis if the circle were centered and expected."'),
  ('Explain unity in your own words, then state whether Study A or Study B reads as more unified, with a reason.', 'Unity means the parts feel intentionally related as a whole. Study A reads as more unified because its bands share a narrow value range, even spacing, and a single clear axis; Study B\'s deliberate variety (uneven spacing, mixed line direction) creates energy at some cost to unity.'),
  ('Design, in words, an original "Study C" that combines calm from Study A with one focal point from Study B. Name the specific elements you would use.', 'Answers vary; must name specific formal elements combined intentionally (e.g., "even horizontal bands like Study A, narrow value range, but one small high-contrast shape placed off-center for a single focal point").'),
  ('Write a full formal-analysis paragraph (5-6 sentences) comparing Study A and Study B, using at least four vocabulary terms from today\'s lesson.', 'Answers vary; must be a coherent paragraph directly comparing both studies, using at least four terms (e.g., balance, emphasis, contrast, value, axis, unity) accurately.'),
  ('Self-assessment: name one formal-analysis term you can now use confidently, and one you still want more practice with.', 'Answers vary; must name a specific term from today\'s vocabulary for each part.')],
 '90-minute session',
 800,
 vocab=[
   ('emphasis', 'a focal area given greater visual attention through contrast'),
   ('balance', 'the distribution of visual weight across a composition'),
   ('value', 'the relative lightness or darkness of a color or tone'),
   ('contrast', 'a strong visual difference that isolates or highlights an element'),
   ('axis', 'an implied or visible line that visual weight is organized around'),
   ('unity', 'the sense that the parts of a composition feel intentionally related'),
 ],
 pacing='Warm-up 8 min · study both compositions + vocabulary 15 min · guided formal-analysis organizer 20 min · partner analysis discussion 15 min · independent practice 22 min · extension work 6 min · assessment 4 min.',
 compositions=['calm', 'tension'])

# --------------------------------------------------------- Engineering Design
add('engineering-design', 'Engineering Design 101: The Paper Tower Challenge — A Full Design Session', 'Engineering Design', 'Engineering / CTE',
 'COURSE-OBJ.ENGR101.2',
 'Define a design problem, distinguish criteria from constraints, generate and compare concepts using a weighted decision matrix, plan a fair test, and justify an evidence-based iteration.',
 'Apply the engineering design process to define a problem, plan a fair test, and justify a design iteration using test evidence rather than guesswork.',
 'A criterion is a desired feature or measure of success ("must support 500 g"); a constraint is a limit the design must obey ("no more than 10 sheets of paper"). Confusing the two leads teams to "solve" the wrong problem. A fair test holds every variable constant except the one being studied, so a failure can be traced to a specific cause. A weighted decision matrix scores each concept against criteria that are not all equally important, multiplying each score by a weight before totaling. Good engineers do not treat a failed prototype as a dead end — they record exactly where and how it failed, then use that evidence to justify one specific, targeted change for the next iteration.',
 [('Sorting criteria from constraints', 'A design brief says: "Build a free-standing tower using no more than 10 sheets of paper and one 12-inch strip of tape, that supports at least 500 g at 30 cm of height, built within 25 minutes." The paper/tape limits and the time limit are constraints (hard limits); "supports at least 500 g" and "at least 30 cm tall" are criteria (measures of success).'),
  ('Reading a weighted decision matrix', 'Three concepts are scored 1-5 on two criteria: Strength (weight x3) and Build speed (weight x1). Concept A scores 4 strength, 5 speed: (4x3)+(5x1)=17. Concept B scores 5 strength, 2 speed: (5x3)+(2x1)=17. Even with a tie, the matrix makes the tradeoff visible instead of hidden.')],
 [('The Design Brief: A Paper Tower Challenge', (
   'The assignment is simple to state and hard to solve well: using no more than 10 sheets of printer paper and one 12-inch strip of tape, build a free-standing tower that supports a textbook (about 500 grams) balanced flat on top, reaches at least 30 centimeters tall, and fits within a 20-by-20-centimeter footprint on the table. Teams have 25 minutes to design, build, and test, and must record every test result, not just the final one.\n\n'
   'Before any paper is folded, each team is required to sort the brief into criteria and constraints on a shared worksheet. The paper limit, the tape limit, the footprint, and the time limit are all constraints: hard limits the design must obey no matter what. The height and the load are criteria: measures the team is trying to hit or beat, and a design that supports 700 grams at 35 centimeters has exceeded the criteria, not just met them. A team that skips this sorting step often wastes early minutes arguing about a limit that was never actually fixed, or, worse, discovers with five minutes left that their beautiful tower is two centimeters short of the height criterion.')),
  ('Two Teams, Two Approaches', (
   'Team Turing rolls all 10 sheets into a single wide column, tapes the seam, and stands it up in under four minutes — by far the fastest build in the room. It easily clears the 30-centimeter height criterion. But when they lower the textbook onto it, the column buckles sideways within two seconds and the book slides to the floor. They try again with the same column shape, taping a second seam for reinforcement; it buckles again, in the same spot, just slightly slower. Their build log shows two failed trials with the same failure mode: no lateral bracing.\n\n'
   'Team Lovelace spends longer planning: they fold four sheets into triangular corner posts, using the geometric fact that a triangle resists changing shape under load far better than a plain cylinder or rectangle does, and use the remaining sheets to form horizontal cross-braces at two heights, widening the base for stability. Their first test holds 500 grams but tips slightly when the book is placed off-center. Reading that result, they widen the base by two centimeters and add one more low cross-brace — a small, targeted change justified directly by where and how the first prototype failed, not a full redesign. The second test holds the book centered and off-center alike, and the structure is measured at 31 centimeters, one centimeter above the height criterion.'))],
 [('In the design brief, list two constraints and explain why they are constraints and not criteria.', 'The 10-sheet/one-tape-strip material limit and the 25-minute time limit are constraints because they are hard limits the design must obey; they are not things to maximize or optimize, unlike criteria.'),
  ('List two criteria from the design brief and explain why they are criteria and not constraints.', 'Supporting at least 500 g and reaching at least 30 cm tall are criteria because they are measures of success a team is trying to meet or exceed, not fixed limits that cannot be crossed.'),
  ('Why does the lesson say a team that skips sorting criteria from constraints "often wastes early minutes"?', 'Without sorting them first, teams may argue about a limit that was never actually fixed, or discover too late that they never confirmed what "success" required, wasting time that could have gone to building and testing.'),
  ('Using Team Turing\'s two trials, identify the controlled variable(s) and the one thing that changed between trials.', 'Controlled: the overall column shape/approach and the load tested. Changed: a second taped seam was added as reinforcement between trial 1 and trial 2 — but the underlying shape (no lateral bracing) stayed the same, which is why the same failure mode repeated.'),
  ('What is a "fair test," and how does Team Turing\'s second trial fail to isolate a new variable?', 'A fair test holds every variable constant except the one being studied. Team Turing\'s second trial changed a seam but kept the same unbraced column shape, so it did not test a genuinely different design idea — it retested a very similar one and got a very similar failure.'),
  ('Explain, using Team Lovelace\'s reasoning, why triangles are used in the design instead of a plain column.', 'A triangle resists changing shape under load better than a plain cylinder or rectangle; Team Lovelace uses this geometric property to brace their corner posts and cross-braces, giving the structure lateral stability that Team Turing\'s column lacked.'),
  ('With a partner, discuss: was Team Turing\'s first build a failure? Use the lesson\'s framing of prototypes to justify your answer.', 'By the lesson\'s framing, a failed prototype is not a dead end but evidence — Team Turing\'s first build revealed a specific failure mode (buckling from no lateral bracing), which is useful information even though the prototype itself did not meet the load criterion.'),
  ('With a partner, identify exactly what evidence justified Team Lovelace\'s second-iteration change (widening the base, adding a brace). Was the change targeted or a full redesign?', 'The evidence was that the first prototype held the load but tipped when off-center; the change (widening the base, adding one low brace) directly targets that specific instability rather than redesigning the whole structure — a targeted, evidence-based iteration.'),
  ('Discuss: which team\'s process better matches the engineering design process described in the lesson, and why?', 'Team Lovelace better matches it: they distinguished criteria from constraints in their planning, used a structural principle (triangulation) deliberately, tested, and made one targeted, evidence-justified change rather than repeating the same untested assumption.'),
  ('Create a two-criterion, two-concept weighted decision matrix using Strength (weight x3) and Cost (weight x2), with your own 1-5 scores, and calculate both totals.', 'Answers vary; must show two concepts each scored 1-5 on both criteria, multiplied by the correct weights (x3 and x2), with correctly calculated totals shown as work.'),
  ('Explain in your own words why a weighted decision matrix is more useful than simply picking a "favorite" concept.', 'A weighted matrix makes tradeoffs explicit and numeric rather than hidden in a gut feeling, and it lets a team weigh criteria that matter more (like strength) more heavily than criteria that matter less (like build speed), producing a more defensible decision.'),
  ('Distinguish accuracy from precision, then explain which one repeated identical test trials mainly demonstrate.', 'Accuracy is closeness to the true value; precision is repeatability of results. Running repeated identical trials mainly demonstrates precision (consistency), though it can also help reveal whether results are accurate if compared to a known standard.'),
  ('Propose one specific safety rule for this challenge and explain the specific risk it addresses.', 'Answers vary; must name a specific rule (e.g., "keep test loads under 1 kg and test at table height, not overhead") tied to a specific risk (e.g., a falling weight or a collapsing structure near hands/eyes).'),
  ('Write a testable claim about paper column strength that a team could investigate with a fair test.', 'Answers vary; must state a specific, testable comparison, e.g., "A triangulated paper column will support more weight than a plain rolled column of the same paper and height," with an implied fair-test setup (same paper, same height, only the shape changes).'),
  ('Using Team Turing\'s data, write one sentence of evidence-based reasoning that could justify their next iteration (which the passage does not describe).', 'Answers vary; must cite the specific failure evidence (buckling from lack of lateral bracing) and propose a targeted change addressing that exact cause, e.g., "Because both trials buckled sideways with no bracing, add diagonal cross-braces at the midpoint."'),
  ('Reflect on tradeoffs: if Team Lovelace had used all 10 sheets for cross-bracing and none for height, what criterion would likely suffer, and why?', 'The height criterion (at least 30 cm) would likely suffer, because using all the material for bracing near the base would leave little paper to build the structure taller — strengthening one criterion (stability) at the direct expense of another (height).'),
  ('Explain why recording every test result, not just the final one, matters to the engineering design process described in this lesson.', 'Every result is evidence; recording failed trials (like Team Turing\'s two identical buckling failures) is what makes it possible to justify a specific next change rather than guessing, and shows whether a change actually fixed the identified problem.'),
  ('Design, in words, one original modification to the paper tower challenge (a new criterion or constraint) and explain what new tradeoff it would create.', 'Answers vary; must propose a specific new criterion or constraint (e.g., "must also survive a small fan blowing on it for 10 seconds") and explain a real resulting tradeoff (e.g., "a wider, heavier base would help but could reduce height achievable with the same material").'),
  ('Write a short paragraph (4-5 sentences) comparing Team Turing\'s and Team Lovelace\'s approaches, using at least three vocabulary terms from today\'s lesson.', 'Answers vary; must be a coherent comparison using at least three terms (e.g., criterion, constraint, fair test, iteration, prototype) accurately applied to the two teams\' described approaches.'),
  ('Self-assessment: name one part of the engineering design process you feel confident applying, and one you want more practice with.', 'Answers vary; must name a specific part of the process described in the lesson (e.g., sorting criteria/constraints, building a decision matrix, planning a fair test, justifying an iteration) for each part.')],
 '90-minute session',
 800,
 vocab=[
   ('criterion', 'a desired feature or measure of success'),
   ('constraint', 'a hard limit the design must obey'),
   ('prototype', 'a testable representation of a design idea'),
   ('fair test', 'holding every variable constant except the one studied'),
   ('iteration', 'a targeted, evidence-justified design change'),
   ('decision matrix', 'a weighted scoring table comparing design concepts'),
 ],
 pacing='Warm-up 8 min · read both passages + vocabulary 15 min · guided criteria/constraints organizer 18 min · partner evidence discussion 18 min · independent practice 22 min · extension work 5 min · assessment 4 min.')

# ------------------------------------------------------------ Psychology 101
add('psychology101-conditioning', 'Psychology 101: Operant Conditioning in Everyday Life — A Full Case-Study Session', 'Psychology 101', 'Psychology',
 'COURSE-OBJ.PSY101.2',
 'Identify reinforcement and punishment (positive/negative) in real behavior-change scenarios and distinguish operant conditioning from classical conditioning.',
 'Apply operant conditioning terms accurately to real scenarios, correctly identifying reinforcement vs. punishment and positive vs. negative in each case.',
 'In operant conditioning, a consequence that follows a behavior changes how often that behavior happens again. "Positive" and "negative" describe whether something is added or removed, not whether the consequence feels good or bad. Positive reinforcement adds something to increase a behavior (a bonus for finishing early). Negative reinforcement removes something unpleasant to increase a behavior (a seatbelt chime stops once you buckle up). Positive punishment adds something to decrease a behavior (a fine for speeding). Negative punishment removes something to decrease a behavior (losing phone privileges). This differs from classical conditioning, where two stimuli are paired (a sound and food) rather than a behavior being followed by a consequence.',
 [('Sorting the four quadrants', 'A dog sits on command and gets a treat (behavior increases) — positive reinforcement, since a treat was added. A driver buckles up and the chime stops (behavior increases) — negative reinforcement, since an unpleasant sound was removed.'),
  ('Distinguishing punishment from reinforcement by outcome', 'A worker is late and loses a bonus (behavior of lateness should decrease) — negative punishment, something was removed. A worker is late and gets a formal write-up (behavior should decrease) — positive punishment, something was added. Reinforcement always aims to increase a behavior; punishment always aims to decrease one.')],
 [('Case File 1: The Late-Arrival Problem', (
   'At Riverside Logistics, dock workers had been clocking in late all month. The shift manager, Dana, tried two different approaches with two different teams to see what would actually change the behavior, rather than guessing.\n\n'
   'With Team A, Dana announced that anyone arriving on time all week would get a $25 bonus on Friday. Clock-in times for Team A improved almost immediately — by Wednesday, only one worker had been late all week, down from an average of four late arrivals per person the month before.\n\n'
   'With Team B, Dana instead announced that anyone late more than once in a week would lose their preferred parking spot for the following week — spots near the door that workers had specifically requested. Team B also improved, though more slowly: late arrivals dropped by about half in the first week and continued dropping through the second week.\n\n'
   'Dana tracked both teams for a full month. Team A\'s improvement happened faster and lasted longer; Team B\'s improvement was real but a few workers seemed to "test" the rule again once the first week passed, requiring a reminder. Dana wrote in her log: "Adding something workers want seems to be outperforming removing something they want, at least for this group, this month."')),
  ('Case File 2: The Barking Problem', (
   'A dog trainer, Marcus, is called in to help a family whose dog, Biscuit, barks constantly at the mail carrier. The family has tried yelling "no" at Biscuit every time he barks, but the barking has continued for three months with no improvement — if anything, it has gotten slightly worse, since Biscuit now seems to bark at Marcus\'s own arrival too.\n\n'
   'Marcus explains that yelling is itself a form of attention, and for some dogs, attention functions as a reward even when it is meant as a correction — meaning the family may have been accidentally reinforcing the exact behavior they wanted to stop. Marcus proposes a different plan: the family will completely ignore Biscuit during mail delivery (removing the attention Biscuit seems to want), and separately, give Biscuit a treat and praise every time the mail carrier passes without barking (adding something Biscuit wants, when the desired behavior — staying quiet — occurs).\n\n'
   'After two weeks of the new plan, Biscuit\'s barking at the mail carrier drops from nearly every delivery to about one bark in five deliveries. Marcus notes that the family\'s original approach was actually reinforcing barking rather than punishing it, even though it felt like a punishment to them.'))],
 [('In Case File 1, classify what happened to Team A using the correct two-word operant conditioning term, and explain using "added vs. removed."', 'Positive reinforcement — a bonus (something desirable) was added, and the target behavior (on-time arrival) increased.'),
  ('In Case File 1, classify what happened to Team B using the correct two-word term, and explain using "added vs. removed."', 'Negative punishment — a preferred parking spot (something desirable) was removed, and the target behavior being discouraged (lateness) decreased.'),
  ('Why does Dana\'s written conclusion use the words "adding" and "removing" instead of "reward" and "punishment"? Connect this to the lesson\'s definitions.', 'The lesson defines positive/negative by whether something is added or removed, not by whether the consequence feels pleasant; using "added/removed" language keeps the analysis precise instead of relying on a vaguer good/bad judgment.'),
  ('In Case File 2, what were the family unintentionally doing every time they yelled at Biscuit, according to Marcus\'s explanation?', 'They were unintentionally providing attention, which functioned as positive reinforcement for barking, even though it was intended as a punishment.'),
  ('Classify Marcus\'s new plan: (a) ignoring Biscuit during mail delivery, and (b) treats/praise for staying quiet. Name each using the correct term.', '(a) Extinction/negative punishment of barking — removing the attention that had been reinforcing it; (b) positive reinforcement of quiet behavior — adding a treat/praise when the dog stays quiet.'),
  ('Explain why the family\'s original approach is described as "reinforcing barking rather than punishing it," even though yelling was meant as a correction.', 'Because attention (even negative-sounding attention like yelling) can function as a reward for an attention-seeking dog; the actual effect on behavior — barking continuing or worsening — is what defines it as reinforcement, not the family\'s intent.'),
  ('With a partner, discuss: why might Team B\'s improvement have been slower and less stable than Team A\'s, based only on evidence in the case, not outside knowledge?', 'The case states a few Team B workers "tested" the rule again after the first week, suggesting the negative punishment needed reinforcement/reminders to hold, while Team A\'s positive reinforcement produced a faster, more sustained change in this specific case.'),
  ('With a partner, design an original one-sentence scenario that demonstrates negative reinforcement, then explain what makes it negative reinforcement rather than positive.', 'Answers vary; must show an unpleasant stimulus being removed when a behavior occurs, increasing that behavior — e.g., "A student turns in homework early and no longer has to hear reminder emails," which is negative because something was taken away, not added.'),
  ('Discuss: is classical conditioning present anywhere in either case file? Use the lesson\'s definition of classical conditioning to justify your answer.', 'No — the lesson defines classical conditioning as pairing two stimuli (like a sound and food) rather than a behavior being followed by a consequence; both case files describe consequences following behaviors, which is operant, not classical, conditioning.'),
  ('Write an original one-sentence example of positive punishment, different from any example in the lesson or case files.', 'Answers vary; must show something added following a behavior, with the behavior intended to decrease, e.g., "A player is benched (extra running drills added) for missing curfew."'),
  ('Write an original one-sentence example of negative punishment, different from any example in the lesson or case files.', 'Answers vary; must show something removed following a behavior, with the behavior intended to decrease, e.g., "A teenager loses car privileges for missing curfew."'),
  ('A classmate says, "Negative always means bad and positive always means good." Correct this misconception using evidence from Case File 1.', 'This is a common misconception; in operant conditioning "positive" means added and "negative" means removed, regardless of whether the outcome is pleasant. In Case File 1, negative punishment (removing a parking spot) is not "positive" just because it worked, and positive reinforcement is not automatically "nicer" than negative punishment — the words describe the mechanism, not the emotional tone.'),
  ('Explain why Marcus\'s plan uses two conditioning strategies at once (ignoring barking AND rewarding quiet) rather than just one.', 'Removing the reinforcement for barking (ignoring it) addresses the behavior to decrease, while separately reinforcing the desired opposite behavior (quiet) gives the dog a clear alternative that is rewarded — using both together builds a replacement behavior rather than just suppressing the old one.'),
  ('If Dana wanted to combine both of her approaches for a new team, propose a plan using both positive reinforcement and negative punishment, and justify each part.', 'Answers vary; must include one element that adds something for good behavior (e.g., a bonus for on-time weeks) and one that removes something for the undesired behavior (e.g., losing a privilege for repeated lateness), each explained using the added/removed logic.'),
  ('Predict what might happen to Team B\'s lateness rates if Dana stopped enforcing the parking-spot rule after one month, and justify your prediction using operant conditioning principles.', 'Lateness would likely increase again, since removing the consequence (extinction) tends to weaken a conditioned behavior change over time unless a new consistent consequence or an intrinsic motivation has taken its place.'),
  ('Identify one ethical consideration the lesson\'s cases raise about using punishment (positive or negative) versus reinforcement to change behavior.', 'Answers vary; must raise a genuine consideration, e.g., punishment can create resentment, fear, or only suppress a behavior temporarily without teaching a replacement behavior, while reinforcement of a desired alternative (as Marcus used) can be more sustainable and less aversive.'),
  ('Write a short original case (4-5 sentences) describing a workplace or classroom scenario, then correctly label the type of operant conditioning used.', 'Answers vary; must include a behavior, a specific consequence, a stated outcome (behavior increases or decreases), and a correct two-word label matching the added/removed and increase/decrease logic.'),
  ('Compare Case File 1 and Case File 2: what is one similarity in how positive reinforcement worked in each case, even though the subjects (workers vs. a dog) are very different?', 'In both cases, adding something the subject wanted (a bonus for workers; a treat/praise for Biscuit) immediately following the desired behavior increased that behavior — the mechanism works the same way across very different subjects.'),
  ('Explain why timing matters in operant conditioning, using evidence from either case file to support your answer.', 'A consequence generally must follow closely after the behavior to shape it effectively; in Case File 2, treats were given right when Biscuit stayed quiet during a delivery, connecting the reward directly to the desired moment rather than to some unrelated later time.'),
  ('Self-assessment: which of the four quadrants (positive reinforcement, negative reinforcement, positive punishment, negative punishment) do you feel least confident identifying, and why?', 'Answers vary; must name one specific quadrant and a genuine reason (e.g., confusing negative reinforcement with punishment because "negative" sounds bad).')],
 '90-minute session',
 800,
 vocab=[
   ('operant conditioning', 'learning where consequences change how often a behavior happens'),
   ('positive', 'something is added following the behavior'),
   ('negative', 'something is removed following the behavior'),
   ('reinforcement', 'a consequence that increases a behavior'),
   ('punishment', 'a consequence that decreases a behavior'),
   ('extinction', 'a behavior decreasing because reinforcement stops'),
 ],
 pacing='Warm-up 8 min · read both case files + vocabulary 15 min · guided quadrant organizer 18 min · partner case discussion 18 min · independent practice 22 min · extension work 5 min · assessment 4 min.')

# ---------------------------------------------------------- College Algebra
add('algebra101-systems', 'College Algebra: Systems of Linear Equations in Context — A Full Problem-Solving Session', 'College Algebra', 'Mathematics',
 'COURSE-OBJ.MATH101.2',
 'Set up and solve systems of two linear equations in two variables using substitution and elimination, and interpret the solution in the context of a real problem.',
 'Translate a real-world scenario into a system of two linear equations, solve it using substitution or elimination, and correctly interpret what the solution means in context.',
 'A system of two linear equations in two variables has a solution wherever both equations are true at once — graphically, where the two lines cross. Substitution solves one equation for a variable and substitutes that expression into the other equation. Elimination adds or subtracts multiples of the equations to cancel a variable. Both methods always give the same answer; the choice is about which is faster for a given system. A system can have exactly one solution (lines cross once), no solution (parallel lines), or infinitely many solutions (the same line written twice) — checking the answer in both original equations catches arithmetic errors before they reach the final interpretation.',
 [('Solving by substitution', 'A gym charges a $40 sign-up fee plus $15/month (y=15x+40); a rival gym charges no sign-up fee but $25/month (y=25x). Setting them equal: 15x+40=25x, so 40=10x, x=4. At x=4 months, both cost y=$100 — the break-even point.'),
  ('Solving by elimination', 'x+y=12 and x-y=2. Adding the equations cancels y: 2x=14, so x=7; substituting back, y=5. Check: 7+5=12 ✓ and 7-5=2 ✓.')],
 [('The Two Gyms Problem: Setting Up the System', (
   'Two gyms are competing for new members near a college campus. Peak Fitness charges a one-time $40 enrollment fee plus $15 per month. Iron Works charges no enrollment fee but $25 per month. A student, Yuki, wants to know exactly when — if ever — the two gyms would cost the same total amount, so she can choose based on how long she plans to stay enrolled, not just the sticker price.\n\n'
   'To answer this precisely, Yuki writes an equation for each gym\'s total cost after x months. For Peak Fitness, the total cost starts at the $40 fee and adds $15 for every month: y = 15x + 40. For Iron Works, the total cost starts at $0 and adds $25 for every month: y = 25x. Together, these two equations form a system — and the question "when do the costs match?" is really asking: for what value of x are both equations true at the same time?\n\n'
   'Yuki solves the system using substitution, since both equations are already solved for y. Setting the two expressions equal: 15x + 40 = 25x. Subtracting 15x from both sides: 40 = 10x, so x = 4. At exactly 4 months, both gyms cost the same total amount: substituting x=4 into either equation gives y = $100. Before month 4, Iron Works is actually cheaper, since Peak Fitness is still paying off its $40 fee; after month 4, Peak Fitness becomes the cheaper option and stays cheaper for every month beyond that, since its rate per month is lower.')),
  ('The Two Gyms Problem: What the Solution Means', (
   'A common mistake is stopping at "x=4" without saying what it means. In this context, x = 4 means "after 4 months of membership," and y = 100 means "both gyms will have cost exactly $100 in total by that point." The solution to a system is not just a pair of numbers — it is the answer to the real question being asked, expressed using the correct units and phrased in a full sentence.\n\n'
   'Yuki double-checks her answer by substituting x=4 back into both original equations separately, rather than trusting the algebra alone. Peak Fitness: y = 15(4) + 40 = 60 + 40 = 100. Iron Works: y = 25(4) = 100. Both equations give y=100 at x=4, confirming the solution is correct in both equations, not just the one she solved for last.\n\n'
   'Yuki then uses the solution to make her actual decision: she plans to be at the college for at least a full academic year, well beyond 4 months, so she chooses Peak Fitness, since it becomes and stays the cheaper option for any membership longer than 4 months. If she had only planned to stay for 2 months, Iron Works would have been the better choice instead — the same system of equations supports either decision, depending on the real constraint (how long she plans to stay) that the algebra alone cannot answer.'))],
 [('Write the equation for Peak Fitness\'s total cost after x months, and identify what each number in the equation represents.', 'y = 15x + 40; 15 is the cost per month, x is the number of months, and 40 is the one-time enrollment fee (the constant/y-intercept).'),
  ('Write the equation for Iron Works\'s total cost after x months, and explain why there is no constant term.', 'y = 25x; there is no constant term because Iron Works has no enrollment fee, so the total cost starts at $0 when x=0.'),
  ('Solve the system 15x+40=25x for x, showing each step.', 'Subtract 15x from both sides: 40=10x. Divide both sides by 10: x=4.'),
  ('Using x=4, find y for each gym\'s equation separately, and explain why both should give the same result.', 'Peak Fitness: y=15(4)+40=100. Iron Works: y=25(4)=100. Both give y=100 because x=4 is the point where the system is satisfied — both equations are true at once by definition of a system\'s solution.'),
  ('Explain, in a full sentence using correct units, what "x=4, y=100" means in the context of this problem.', 'After 4 months of membership, both Peak Fitness and Iron Works will have cost a total of $100.'),
  ('Solve this new system using elimination and show your work: x+y=12 and x-y=2.', 'Adding the equations: 2x=14, so x=7. Substituting into x+y=12: 7+y=12, so y=5. Solution: x=7, y=5.'),
  ('With a partner, check the elimination answer (x=7, y=5) in both original equations and explain why checking both — not just one — matters.', 'x+y=12 → 7+5=12 ✓; x-y=2 → 7-5=2 ✓. Checking both matters because an arithmetic slip in one equation might still satisfy the other equation by coincidence, so only checking both confirms the solution is genuinely correct.'),
  ('With a partner, discuss: for months 1 through 3, which gym is cheaper, and how does this relate to the x=4 solution?', 'For months 1-3, Peak Fitness is more expensive because the $40 fee has not yet been "paid off" by its lower monthly rate; Iron Works is cheaper until the two lines cross at x=4, after which Peak Fitness becomes and stays cheaper.'),
  ('Discuss: why is x=4 called a "break-even point," and what would change about Yuki\'s decision if she planned to stay for exactly 4 months?', 'It is called a break-even point because the two costs are exactly equal there — neither gym is more or less expensive. If Yuki planned to stay for exactly 4 months, both gyms would cost the same total ($100), so the choice would not matter financially and she could decide based on other factors (location, equipment, etc.).'),
  ('Set up (but do not solve) a system of equations for two phone plans: Plan A costs $20/month with no activation fee; Plan B costs $10/month plus a $60 activation fee.', 'y=20x for Plan A; y=10x+60 for Plan B, where x is the number of months and y is the total cost.'),
  ('Solve the phone plan system from the previous question using substitution, showing every step.', '20x=10x+60. Subtract 10x from both sides: 10x=60. Divide by 10: x=6. Substituting into y=20x: y=120. Solution: x=6, y=120.'),
  ('Interpret the phone plan solution in a full sentence with correct units.', 'After 6 months, both phone plans will have cost a total of $120.'),
  ('Solve this system using elimination and show your work: 2x+3y=16 and 2x-y=4.', 'Subtracting the equations: (2x+3y)-(2x-y)=16-4, so 4y=12, y=3. Substituting into 2x-y=4: 2x-3=4, so 2x=7, x=3.5.'),
  ('Explain what it would mean, graphically, if a system of two linear equations had no solution, and give an example of when this could happen in a real cost-comparison scenario.', 'No solution means the two lines are parallel and never cross — the two costs are never exactly equal at any x. This could happen if two plans had the same monthly rate but different starting fees; the gap between their total costs would stay constant and never reach zero.'),
  ('Explain what it would mean if a system of two linear equations had infinitely many solutions, and why this would be an unusual result for two different pricing plans.', 'Infinitely many solutions means the two equations describe the same line; every x-value would be a solution. This would be unusual for pricing plans because it would mean two "different" plans actually have identical cost structures (same rate and same starting fee) — effectively the same plan.'),
  ('A classmate solves 15x+40=25x by writing "x=40/10=4" without showing the subtraction step. Explain what step they skipped and why showing it matters.', 'They skipped subtracting 15x from both sides (or an equivalent step) before dividing; showing it matters because it demonstrates the equation was solved correctly rather than the answer being guessed or memorized, and it helps catch errors in later, more complex systems.'),
  ('Create your own original two-plan cost-comparison scenario (e.g., ride-share apps, streaming services) and write the system of two equations that models it.', 'Answers vary; must include two distinct linear equations in the same two variables (total cost y and units x, e.g., months or rides), each with realistic-looking constants matching a described real scenario.'),
  ('Solve the system you created in the previous question, showing your full method (substitution or elimination).', 'Answers vary; work must correctly solve the student\'s own system and arrive at a solution consistent with their two equations.'),
  ('Interpret your solution from the previous question in a full sentence with correct units, matching the format used in the gym example.', 'Answers vary; must state the x-value with correct units (e.g., "after 5 rides") and the y-value with correct units (e.g., "both apps cost $45"), matching the interpretation style modeled in the lesson.'),
  ('Self-assessment: which method (substitution or elimination) do you personally find faster, and describe one type of system where you would choose the other method instead.', 'Answers vary; must name a genuine preference and describe a specific system type (e.g., "when both equations are already solved for y, substitution is faster; when the coefficients line up for easy cancellation, I\'d use elimination instead").')],
 '90-minute session',
 800,
 vocab=[
   ('system of equations', 'two or more equations sharing the same variables'),
   ('substitution', 'solving one equation for a variable, then substituting it into the other'),
   ('elimination', 'adding/subtracting equations to cancel a variable'),
   ('break-even point', 'the input where two totals become equal'),
   ('no solution', 'parallel lines; the system is never true at once'),
   ('infinitely many solutions', 'the two equations describe the same line'),
 ],
 pacing='Warm-up 8 min · read both worked passages + vocabulary 15 min · guided systems organizer 18 min · partner check-and-discuss 18 min · independent practice 22 min · extension work 5 min · assessment 4 min.')

# ---------------------------------------------------------------- Biology 101
add('biology101-respiration', 'Biology 101: Cellular Respiration and Energy Flow — A Full Reading and Application Session', 'Biology 101', 'Biology',
 'COURSE-OBJ.BIO101.2',
 'Explain the three stages of cellular respiration and how each stage\'s ATP yield and oxygen requirement connect to a real physiological scenario.',
 'Explain how glycolysis, the Krebs cycle, and the electron transport chain each contribute to ATP production, and apply this to real exercise-physiology scenarios.',
 'Cellular respiration converts glucose into usable energy (ATP) in three connected stages. Glycolysis happens in the cytoplasm, needs no oxygen, and produces a small, quick yield of 2 ATP. The Krebs cycle happens in the mitochondrial matrix, requires oxygen indirectly (it only proceeds if the electron transport chain is running), and produces 2 more ATP plus electron carriers. The electron transport chain, in the inner mitochondrial membrane, uses oxygen directly as the final electron acceptor and produces the large majority of ATP — roughly 32-34 per glucose. When oxygen is scarce, cells fall back on anaerobic fermentation after glycolysis, which is fast but yields far less energy and produces lactic acid as a byproduct.',
 [('Comparing the ATP yield of each stage', 'Glycolysis yields 2 ATP (no oxygen needed); the Krebs cycle yields 2 more ATP (needs oxygen indirectly); the electron transport chain yields roughly 32-34 ATP (needs oxygen directly). The electron transport chain alone accounts for the large majority of total energy from one glucose molecule.'),
  ('Reading an oxygen-availability scenario', 'During an all-out 100-meter sprint, oxygen delivery to muscle cells cannot keep pace with demand, so cells rely heavily on glycolysis followed by anaerobic fermentation — fast ATP, but a small yield, with lactic acid building up as a result.')],
 [('Reading the Three Stages: A Step-by-Step Overview', (
   'Every cell needs a steady supply of ATP, the molecule cells spend as usable energy, and most of that ATP comes from breaking down glucose through three connected stages. The first stage, glycolysis, takes place in the cytoplasm, outside the mitochondria entirely, and splits one glucose molecule into two molecules of pyruvate. Glycolysis does not require oxygen and produces a net gain of only 2 ATP — small, but fast, and available even when oxygen is limited.\n\n'
   'If oxygen is available, the pyruvate from glycolysis moves into the mitochondria for the second stage, the Krebs cycle (also called the citric acid cycle). Here, each pyruvate is broken down further, releasing carbon dioxide and producing a small additional amount of ATP directly (about 2 total), but more importantly, generating electron carriers (NADH and FADH2) that will fuel the next stage. The Krebs cycle itself does not use oxygen directly, but it grinds to a halt if oxygen is not available downstream, because it depends on the electron transport chain to recycle the electron carriers it needs to keep running.\n\n'
   'The third stage, the electron transport chain, takes place across the inner mitochondrial membrane and is where oxygen is used directly, as the final acceptor of the electrons passed along the chain. This stage produces the vast majority of the cell\'s ATP from one glucose molecule — roughly 32 to 34 ATP, dwarfing the combined total from the first two stages. This is why the presence or absence of oxygen makes such a dramatic difference to how much energy a cell can extract from the same amount of glucose.')),
  ('Applying the Stages: Sprinting vs. Distance Running', (
   'A 100-meter sprinter and a marathon runner both rely on cellular respiration, but their muscles draw on it very differently because of how quickly oxygen can be delivered to working muscle cells. During an all-out sprint, the demand for ATP spikes far faster than the bloodstream can deliver oxygen to muscle tissue, even though the runner is breathing hard. With oxygen effectively unavailable at the rate needed, muscle cells lean almost entirely on glycolysis, and because the pyruvate produced cannot be fully processed through the Krebs cycle and electron transport chain fast enough, cells shift to anaerobic fermentation: pyruvate is converted into lactic acid, allowing glycolysis to keep running quickly, but at a steep cost in total ATP yield per glucose molecule.\n\n'
   'A marathon runner\'s muscles, by contrast, operate at a pace where the cardiovascular system can keep delivering oxygen throughout the race. This allows working muscle cells to run the full three-stage process — glycolysis, the Krebs cycle, and the electron transport chain — continuously, extracting the much larger ATP yield available when oxygen is present. This is a major reason marathon training emphasizes cardiovascular conditioning: the goal is to improve how efficiently oxygen reaches muscle cells, keeping them running the high-yield aerobic pathway for as long as possible rather than being forced into the low-yield anaerobic pathway.\n\n'
   'The lactic acid buildup from a sprinter\'s anaerobic fermentation is also why sprinters feel a burning sensation in their muscles that marathon runners, pacing themselves aerobically, generally avoid until very late in a race, if at all.'))],
 [('Name the three stages of cellular respiration in order, and state where in the cell each one occurs.', 'Glycolysis (cytoplasm), the Krebs cycle (mitochondrial matrix), and the electron transport chain (inner mitochondrial membrane).'),
  ('Which stage does not require oxygen at all, and approximately how much ATP does it produce?', 'Glycolysis does not require oxygen and produces a net gain of about 2 ATP.'),
  ('Explain why the Krebs cycle is described as needing oxygen "indirectly" rather than directly.', 'The Krebs cycle itself does not consume oxygen, but it depends on the electron transport chain to recycle its electron carriers (NADH/FADH2); if oxygen is unavailable for the electron transport chain, the Krebs cycle stops running because it has nowhere to send those carriers.'),
  ('Which stage produces the large majority of ATP from one glucose molecule, and approximately how many ATP does it yield?', 'The electron transport chain, yielding roughly 32-34 ATP.'),
  ('In the sprinting passage, explain specifically why a sprinter\'s muscle cells cannot rely on the electron transport chain during an all-out sprint.', 'The demand for ATP during an all-out sprint spikes faster than the bloodstream can deliver oxygen to the muscle cells, so there is not enough oxygen available at the rate needed to keep the electron transport chain (and the Krebs cycle feeding it) running at that pace.'),
  ('What happens to pyruvate during anaerobic fermentation, and why does this process exist?', 'Pyruvate is converted into lactic acid; this allows glycolysis to keep running quickly by recycling the molecules glycolysis needs, even without oxygen, though at a much lower total ATP yield.'),
  ('With a partner, explain why a marathon runner\'s training emphasizes cardiovascular conditioning, connecting this directly to ATP yield.', 'Better cardiovascular conditioning improves how efficiently oxygen reaches muscle cells, which keeps cells running the high-yield aerobic pathway (all three stages) rather than being forced into the low-yield anaerobic pathway, maximizing ATP produced per glucose molecule.'),
  ('With a partner, discuss: why do sprinters typically feel a muscle "burn" that marathon runners mostly avoid, according to the passage?', 'The burning sensation is associated with lactic acid buildup from anaerobic fermentation, which sprinters rely on heavily due to oxygen delivery limits during an all-out effort; marathon runners, pacing aerobically, generally avoid this buildup until very late in a race, if at all.'),
  ('Discuss: if a runner\'s cardiovascular system improved significantly through training, what specific change would you expect in their muscle cells\' ATP source during a sustained run, and why?', 'You would expect muscle cells to rely more on the full three-stage aerobic pathway (and less on anaerobic fermentation) for longer, since improved oxygen delivery lets cells keep running the higher-yield electron transport chain instead of switching to the lower-yield anaerobic pathway.'),
  ('Calculate the approximate total ATP yield from all three stages combined, showing your addition.', '2 (glycolysis) + 2 (Krebs cycle) + roughly 32-34 (electron transport chain) = approximately 36-38 ATP total per glucose molecule.'),
  ('Explain why the electron transport chain "dwarfs" the ATP contribution of the first two stages combined, using the numbers from the lesson.', 'Glycolysis and the Krebs cycle together produce only about 4 ATP directly, while the electron transport chain alone produces roughly 32-34 ATP — more than eight times as much as the first two stages combined.'),
  ('A student claims "glycolysis is useless because it makes so little ATP." Use evidence from the lesson to argue against this claim.', 'Glycolysis is not useless: it is the only stage that runs without oxygen, making it essential during high-intensity effort (like sprinting) when oxygen cannot be delivered fast enough, and it also supplies the pyruvate that feeds the higher-yield stages when oxygen is available.'),
  ('Predict what would happen to a sprinter\'s ATP production if they tried to run a marathon pace using only the anaerobic pathway the entire time, and explain why this would be unsustainable.', 'ATP yield per glucose molecule would stay very low throughout the race, requiring the body to burn through glucose stores far faster for the same energy output, and lactic acid would build up continuously rather than being cleared — this combination would be physically unsustainable over a marathon\'s distance.'),
  ('Explain the relationship between the Krebs cycle and the electron transport chain using the phrase "electron carriers" in your answer.', 'The Krebs cycle produces electron carriers (NADH and FADH2) that carry high-energy electrons to the electron transport chain; the electron transport chain uses those electrons, along with oxygen as the final acceptor, to produce the majority of the cell\'s ATP.'),
  ('Design a short original scenario (not sprinting or marathon running) where a cell or organism would rely mainly on anaerobic fermentation, and justify your choice.', 'Answers vary; must describe a low-oxygen scenario (e.g., yeast fermenting in a sealed container, muscle cells during a brief maximal lift) and justify it using the oxygen-limitation logic from the lesson.'),
  ('Write a two-to-three sentence explanation of why "more oxygen available" generally means "more ATP produced," using specific stage names.', 'Answers vary; must connect oxygen availability to the electron transport chain running (and therefore the Krebs cycle continuing to feed it), explaining that this combination produces far more ATP than glycolysis and fermentation alone.'),
  ('Compare the two passages: what specific piece of evidence from "Applying the Stages" directly illustrates the general fact stated in "Reading the Three Stages" that oxygen absence causes "such a dramatic difference" in ATP yield?', 'The sprinter\'s reliance on glycolysis and anaerobic fermentation (low yield) versus the marathon runner\'s ability to run the full three-stage aerobic pathway (high yield) directly illustrates the general point that oxygen availability dramatically changes total ATP output.'),
  ('Write an original two-to-three sentence summary explaining cellular respiration to someone who has never taken a biology course, without using the words "mitochondria" or "ATP."', 'Answers vary; must accurately convey the general concept (cells break down food/sugar in stages to make usable energy, and having enough oxygen lets them make much more of that energy) using accessible language.'),
  ('Explain why holding your breath briefly during a heavy weightlifting rep does not immediately stop your muscle cells from producing ATP.', 'Muscle cells can still run glycolysis and anaerobic fermentation without a fresh oxygen supply during a brief effort, so ATP production continues at a reduced (anaerobic) rate even while breath is held, though this pathway cannot sustain the same output for long.'),
  ('Self-assessment: which of the three stages do you feel most confident explaining, and which do you want more practice with?', 'Answers vary; must name a specific stage (glycolysis, Krebs cycle, or electron transport chain) for each part.')],
 '90-minute session',
 800,
 vocab=[
   ('ATP', 'the molecule cells use as usable chemical energy'),
   ('glycolysis', 'the oxygen-free first stage, splitting glucose in the cytoplasm'),
   ('Krebs cycle', 'the second stage, generating electron carriers in the mitochondria'),
   ('electron transport chain', 'the third stage; uses oxygen directly, yields most ATP'),
   ('anaerobic fermentation', 'a low-yield backup pathway used without enough oxygen'),
   ('lactic acid', 'a byproduct of anaerobic fermentation in muscle cells'),
 ],
 pacing='Warm-up 8 min · read both passages + vocabulary 15 min · guided stage-by-stage organizer 18 min · partner application discussion 18 min · independent practice 22 min · extension work 5 min · assessment 4 min.')

# ------------------------------------------------------- English Composition I
add('composition101-revision', 'English Composition I: Revising for Evidence — A Full Workshop Session', 'English Composition I', 'English/Writing',
 'COURSE-OBJ.ENGL101.2',
 'Revise a thesis-driven paragraph by replacing generalizations with specific evidence and explicit analysis connecting that evidence back to the claim.',
 'Identify unsupported generalizations in a draft paragraph and revise them into evidence-based analysis that explicitly connects evidence to a claim.',
 'A strong body paragraph makes a specific claim, supports it with concrete evidence (a quotation, statistic, or detailed example), and then analyzes that evidence — explaining, in the writer\'s own words, how it proves the claim. A common early-draft weakness is the "unsupported generalization": a broad claim ("Social media affects teenagers a lot") with no specific evidence attached. Revision is not about adding more words; it is about replacing vague claims with specific evidence and adding analysis that explains why the evidence matters, rather than just dropping a quotation in and moving on ("quote-dropping").',
 [('Spotting an unsupported generalization', '"Exercise is good for students." — This is too broad and has no evidence attached. A revised version names a specific effect and cites specific evidence: "Students who exercised for 30 minutes before a test scored 15% higher on average, according to a 2019 study of 200 undergraduates (Chen, 2019)."'),
  ('Fixing quote-dropping with analysis', 'Weak: "The author writes \'the city forgot how to breathe\' (12). This shows pollution is bad." Revised: the same quotation is kept, but analysis is added explaining specifically how the metaphor of a city "forgetting to breathe" personifies pollution as a kind of suffocation, making an abstract environmental problem feel physically urgent to the reader.')],
 [('Draft Paragraph: Before Revision', (
   'Here is a student\'s early draft paragraph, written for an essay arguing that a particular city park should receive more funding for maintenance.\n\n'
   '"Riverside Park is really important to the community. A lot of people use it every day, and it means a lot to different kinds of people. The park has been around for a long time and everyone has memories there. It would be sad if the park fell into disrepair because it matters so much to so many people. The city should definitely give the park more funding because it deserves it."\n\n'
   'This paragraph has a claim buried in it (the park deserves more funding because it matters to the community), but every sentence supporting that claim is a generalization: "a lot of people," "means a lot," "for a long time," "matters so much." None of these phrases point to a specific, checkable piece of evidence a reader could verify or picture. The paragraph also never explains why community importance should translate into funding — it just repeats the claim in slightly different words each time, a pattern sometimes called "circular" writing.')),
  ('Revised Paragraph: After Adding Evidence and Analysis', (
   'Here is the same paragraph after the student revised it using a city parks-department attendance report and a short interview with a local resident, replacing every generalization with something specific.\n\n'
   '"Riverside Park served an estimated 40,000 visitors last year, according to the city parks department\'s 2025 attendance report — more than any other park in the district. That number includes a weekly farmers\' market that brings in over 300 vendors and shoppers each Saturday, a youth soccer league with six teams, and, according to longtime resident Maria Ibarra, three generations of her own family who have picnicked there every summer since the park opened in 1987. This is not a park used occasionally by a few people; it is a piece of daily infrastructure for thousands of residents across different age groups and community roles, from small-business vendors to youth athletes to multigenerational families. Funding is directly tied to this scale of use: a facility serving 40,000 annual visitors carries a level of wear, from foot traffic to equipment use, that a city\'s general maintenance budget was never designed to absorb without a dedicated allocation."\n\n'
   'Notice that the revision does not just add numbers for their own sake — each piece of evidence (the attendance figure, the market vendor count, the interview detail) is followed by analysis explaining specifically why that evidence supports the funding claim, rather than being dropped in and left to speak for itself.'))],
 [('Identify one unsupported generalization from the "Before" paragraph and explain what specific information is missing from it.', 'Answers vary; e.g., "A lot of people use it every day" is missing a specific number, source, or time frame — the reader cannot verify or picture how many people or how often.'),
  ('What is the buried claim in the "Before" paragraph, and why is it difficult to find on a first read?', 'The claim is that the park deserves more funding because it matters to the community; it is difficult to find because it is repeated in different generalized phrasings ("really important," "means a lot," "deserves it") rather than stated once clearly and then supported.'),
  ('What does the lesson mean by "circular" writing, and where does the "Before" paragraph show this pattern?', 'Circular writing repeats a claim in different words instead of supporting it with new evidence; the "Before" paragraph restates "the park matters" four different ways (important, means a lot, sad if it fell into disrepair, deserves funding) without ever adding a specific supporting detail.'),
  ('Name the two specific evidence sources the student used in the "After" paragraph.', 'A city parks-department 2025 attendance report, and a short interview with local resident Maria Ibarra.'),
  ('Find one sentence in the "After" paragraph that is evidence, and one sentence (or clause) that is analysis explaining that evidence. Label each.', 'Answers vary; e.g., Evidence: "Riverside Park served an estimated 40,000 visitors last year..."; Analysis: "a facility serving 40,000 annual visitors carries a level of wear...that a city\'s general maintenance budget was never designed to absorb."'),
  ('Explain, using the lesson\'s own definition, why simply adding the attendance number without the final sentence about wear-and-tear would still be "quote-dropping" rather than full revision.', 'The lesson defines quote-dropping as citing evidence without analysis explaining how it proves the claim; the number alone shows usage but does not explain why heavy usage means the maintenance budget specifically needs more funding — the analysis sentence is what completes the connection to the claim.'),
  ('With a partner, revise this generalization into a specific, evidence-based sentence: "The cafeteria food is unhealthy." Invent plausible, clearly-labeled hypothetical evidence.', 'Answers vary; must replace the vague claim with a specific, labeled hypothetical detail, e.g., "In a hypothetical survey of 50 students, 38 reported that fried items made up more than half of the entrée options over a two-week period."'),
  ('With a partner, discuss: why might the "After" paragraph\'s interview detail (three generations of one family) be more persuasive to some readers than the attendance statistic, even though it describes only one family?', 'A specific human story can create an emotional, concrete connection that a statistic alone does not; readers may relate more easily to one family\'s multigenerational experience than to an abstract number, even though the statistic demonstrates broader scale — strong paragraphs often use both types of evidence together.'),
  ('Discuss: is it possible to over-rely on statistics and under-rely on human examples (or vice versa) in a paragraph like this? What would that look like?', 'Answers vary; must describe an imbalance, e.g., an all-statistics paragraph might feel cold or abstract and lose the human stakes, while an all-anecdote paragraph might feel unrepresentative or anecdotal without showing broader scale — a strong paragraph typically balances both.'),
  ('Rewrite this generalization into a specific claim with labeled hypothetical evidence and one sentence of analysis: "Online classes are convenient for students."', 'Answers vary; must include a specific labeled hypothetical detail (e.g., a made-up but clearly labeled statistic or example) and a sentence explaining why that evidence supports the convenience claim specifically.'),
  ('Identify the single most vague sentence in the "Before" paragraph, in your judgment, and explain your reasoning for choosing it over the others.', 'Answers vary; must select one sentence and justify the choice by naming specifically what information (number, source, example) is missing compared to the other vague sentences.'),
  ('Explain how the "After" paragraph\'s topic sentence differs in function from its supporting sentences.', 'The topic sentence (the attendance figure) introduces the paragraph\'s central evidence-backed point, while the supporting sentences add further specific detail (the market, the league, the interview) and then analysis connecting all of it back to the funding claim.'),
  ('A classmate revises their paragraph by adding three new statistics but no analysis sentences at all. Using the lesson\'s vocabulary, name the specific problem with this revision.', 'This is quote-dropping (or the statistical equivalent of it) — evidence without analysis; adding statistics alone does not explain how or why that evidence supports the claim, which is required for a fully revised paragraph.'),
  ('Write one original unsupported generalization (on any topic of your choice), then revise it into a specific, evidence-based sentence with labeled hypothetical evidence.', 'Answers vary; the original sentence must be a genuine generalization (vague, no specifics), and the revision must add a specific, clearly labeled hypothetical detail supporting it.'),
  ('Add one sentence of analysis to the evidence-based sentence you just wrote, explaining how it supports your original claim.', 'Answers vary; the analysis sentence must explicitly connect the evidence back to the claim, explaining the "why," not just restating the evidence.'),
  ('Explain why "adding more words" is explicitly not the same as revision, according to the lesson.', 'The lesson states that revision is about replacing vague claims with specific evidence and analysis, not about length; a longer paragraph that is still full of generalizations has not actually been revised in the way the lesson describes.'),
  ('Compare the "Before" and "After" paragraphs\' final sentences. How does the function of the final sentence change between the two drafts?', 'The "Before" paragraph\'s final sentence restates the claim ("the city should give the park more funding") without new support; the "After" paragraph\'s final sentence provides genuine analysis, explicitly explaining why the scale of usage translates into a funding need — a stronger, more functional conclusion to the paragraph\'s argument.'),
  ('Write a two-to-three sentence explanation, in your own words, of the difference between evidence and analysis, using an original example (not from this lesson).', 'Answers vary; must clearly distinguish evidence (a specific fact, quotation, or data point) from analysis (the writer\'s explanation of how that evidence supports a claim), illustrated with a new example.'),
  ('Explain why a paragraph could have strong evidence but still fail as an argument if the analysis is missing.', 'Evidence alone shows something is true but does not explain why it matters to the claim; without analysis connecting the evidence back to the argument, a reader is left to guess the writer\'s reasoning, which weakens the paragraph\'s persuasive power even if the evidence itself is solid.'),
  ('Self-assessment: in your own recent writing, do you tend to under-use evidence, under-use analysis, or both? Give one specific example from your own experience if possible.', 'Answers vary; must reflect honestly and specifically on the student\'s own writing habits, naming evidence, analysis, or both as an area of growth.')],
 '90-minute session',
 800,
 vocab=[
   ('claim', 'the specific, arguable point a paragraph is making'),
   ('evidence', 'a specific, checkable fact, quotation, or data point'),
   ('analysis', 'the writer\'s explanation of how evidence supports a claim'),
   ('generalization', 'a broad, vague statement with no specific evidence attached'),
   ('quote-dropping', 'citing evidence without explaining how it proves the claim'),
   ('circular writing', 'restating a claim in different words instead of supporting it'),
 ],
 pacing='Warm-up 8 min · read both drafts + vocabulary 15 min · guided evidence/analysis organizer 18 min · partner revision workshop 18 min · independent practice 22 min · extension work 5 min · assessment 4 min.')

# ------------------------------------------------------------- US History I
add('ushistory101-convention', 'US History I: The Constitutional Convention — Compromise in Practice — A Full Source-Analysis Session', 'US History I', 'History',
 'COURSE-OBJ.HIST101.2',
 'Analyze how the Great Compromise and the Three-Fifths Compromise each resolved a specific conflict at the 1787 Constitutional Convention, and evaluate the tradeoffs each compromise created.',
 'Explain the specific conflicts behind the Great Compromise and the Three-Fifths Compromise, and evaluate what each compromise resolved and what it left unresolved.',
 'The 1787 Constitutional Convention nearly collapsed over how states would be represented in the new Congress. Large states backed the Virginia Plan (representation by population); small states backed the New Jersey Plan (equal representation per state), fearing large states would dominate. The Great Compromise (Connecticut Compromise) created a bicameral Congress: the House by population, the Senate equal per state. A second, harder conflict was whether enslaved people would count toward a state\'s population for representation and taxation. The Three-Fifths Compromise counted each enslaved person as three-fifths of a person for both purposes — a deliberately partial, dehumanizing formula that gave slaveholding states more congressional power than their free population alone would have earned, without acknowledging enslaved people\'s full humanity or granting them any rights.',
 [('Reading the representation conflict', 'Virginia (large population) wanted representation by population, which would give it more seats than small states like Delaware. Delaware wanted equal representation per state, protecting its voice regardless of population. Neither side would ratify a Constitution built entirely on the other\'s plan.'),
  ('Reading the compromise formula', 'The Three-Fifths Compromise: a state with 100,000 free residents and 40,000 enslaved people would count 100,000 + (40,000 × 3/5) = 124,000 people for representation — more seats than its free population alone would earn, but fewer than counting all 140,000 residents equally.')],
 [('Source A: The Convention Debate, Summer 1787', (
   'By mid-June 1787, the convention delegates meeting in Philadelphia were at an impasse. Delegates from Virginia, the most populous state, had proposed what became known as the Virginia Plan: a Congress with representation based on each state\'s population, along with an executive and judiciary chosen partly through that legislature. Large states supported this plan because it reflected their greater population, and delegates like James Madison argued that a government should represent people, not simply the abstract entity of a "state."\n\n'
   'Delegates from smaller states, including New Jersey and Delaware, rejected this framework outright. William Paterson of New Jersey introduced a rival proposal, the New Jersey Plan, keeping something closer to the existing Articles of Confederation structure: one vote per state, regardless of population. Small-state delegates argued that population-based representation would let a handful of large states dominate every vote, effectively erasing small states\' influence in the national government they were being asked to join.\n\n'
   'The debate grew heated enough that several delegates threatened to walk out, and for a period in late June and early July, the convention itself appeared close to collapse. Roger Sherman and Oliver Ellsworth of Connecticut proposed a middle path: a two-chamber legislature, with one chamber (the House of Representatives) apportioned by population, satisfying large states, and a second chamber (the Senate) giving each state two votes regardless of size, satisfying small states. On July 16, 1787, this proposal — the Great Compromise, or Connecticut Compromise — passed by a narrow vote of five states to four, breaking the deadlock and allowing the convention to continue.')),
  ('Source B: The Representation-and-Taxation Problem', (
   'Even after the Great Compromise resolved how many representatives each state would have relative to other states, a second, harder question remained: when counting a state\'s population to determine that number of representatives (and, separately, to calculate direct taxes owed to the federal government), would enslaved people be counted at all?\n\n'
   'Delegates from Southern states, where enslaved people made up a large share of the total population, argued for counting enslaved people fully for the purpose of representation — which would significantly increase those states\' number of seats in the House — while generally preferring not to count them for taxation, which would reduce what those states owed. Delegates from Northern states, where slavery was less economically central, argued the opposite on each point: they opposed counting enslaved people for representation, since enslaved people had no political rights or voice, but were more willing to count them for taxation purposes.\n\n'
   'The convention settled on a single formula applied to both calculations: each enslaved person would count as three-fifths of a person, both for determining a state\'s number of representatives and for calculating direct taxes. This satisfied neither side\'s underlying principle — it was not based on any coherent argument about a person being "three-fifths human" — but it was a numerical compromise that both blocs could accept because it produced a workable, if deeply unjust, middle number between "count fully" and "do not count at all." The compromise gave slaveholding states meaningfully more congressional power and influence in presidential elections (through the Electoral College, which was tied to House seats) than their free population alone would have earned, while enslaved people themselves gained no rights, representation, or voice from being "counted" at all.'))],
 [('What was the core disagreement between the Virginia Plan and the New Jersey Plan?', 'The Virginia Plan proposed representation in Congress based on state population; the New Jersey Plan proposed equal representation per state regardless of population — large and small states disagreed over which principle should govern.'),
  ('Why did small states like Delaware and New Jersey specifically oppose the Virginia Plan?', 'They feared that population-based representation would let a handful of large states dominate every vote, effectively erasing small states\' influence in the national government.'),
  ('Describe the specific structure of the Great Compromise: what determines representation in each of the two chambers?', 'The House of Representatives is apportioned by population (satisfying large states); the Senate gives each state two votes regardless of population (satisfying small states).'),
  ('According to Source A, how close did the convention come to failing before the Great Compromise passed, and what evidence supports this?', 'The convention came close to collapsing; the passage states several delegates threatened to walk out and the convention "appeared close to collapse" in late June and early July, with the compromise passing by a narrow vote of five states to four.'),
  ('What two purposes did the "count enslaved people" question affect, according to Source B?', 'Representation in the House of Representatives, and the calculation of direct taxes owed to the federal government.'),
  ('Explain the apparent contradiction in Southern delegates\' position on counting enslaved people for representation versus taxation, and why this was not actually inconsistent from their perspective.', 'Southern delegates wanted enslaved people counted fully for representation (to gain more House seats) but not counted for taxation (to owe less tax); this was self-interested rather than inconsistent — in both cases, they were arguing for whichever count benefited their states most.'),
  ('With a partner, explain why Northern delegates took the reverse position from Southern delegates on the same two questions.', 'Northern delegates opposed counting enslaved people for representation (since enslaved people had no political rights or voice, they saw this as unjustly inflating Southern power) but were more willing to count them for taxation, which would raise what Southern states owed — again, a position aligned with what benefited Northern states\' relative power.'),
  ('With a partner, discuss: the lesson states the three-fifths formula "was not based on any coherent argument about a person being three-fifths human." What does this reveal about how the compromise was actually reached?', 'It reveals the formula was a purely numerical, political compromise between two competing self-interested positions (count fully vs. not at all), not a principled judgment about the value or humanity of enslaved people — a middle number both blocs could accept, unrelated to any moral reasoning.'),
  ('Discuss: Source B states the compromise "satisfied neither side\'s underlying principle." Explain what each side\'s underlying principle actually was.', 'The South\'s underlying (self-interested) principle was maximizing representation while minimizing taxation; the North\'s underlying principle was the reverse. The three-fifths formula gave neither side their full preferred outcome on either count, since it was fully applied to both.'),
  ('Using Source B, explain how the Three-Fifths Compromise affected presidential elections, not just Congress.', 'Because Electoral College votes were tied to a state\'s total number of representatives (House seats plus senators), counting enslaved people as three-fifths of a person for representation also gave slaveholding states more Electoral College votes than their free population alone would have earned.'),
  ('Evaluate: did the Three-Fifths Compromise give enslaved people any rights or representation? Justify your answer using Source B.', 'No — Source B explicitly states enslaved people "gained no rights, representation, or voice from being counted at all"; the count affected only how much political power slaveholding states held, not enslaved people\'s own status or rights.'),
  ('Compare the Great Compromise and the Three-Fifths Compromise: what problem did each one solve, stated in one sentence each?', 'The Great Compromise solved how state population should determine congressional representation between large and small states; the Three-Fifths Compromise (nominally) resolved whether and how much enslaved people would count toward that same representation and toward taxation.'),
  ('Using evidence from both sources, explain why the convention needed two separate compromises rather than one.', 'The two conflicts were distinct: the Great Compromise addressed disagreement between large and small states over population-based representation in general, while the Three-Fifths Compromise addressed a separate disagreement between Northern and Southern states specifically over whether enslaved people counted toward that population — resolving one did not resolve the other.'),
  ('A classmate claims "the Great Compromise and the Three-Fifths Compromise were basically the same kind of compromise." Evaluate this claim using specific evidence from both sources.', 'This claim oversimplifies: the Great Compromise balanced two competing but comparably-positioned political interests (large vs. small states) through a structural solution (two chambers); the Three-Fifths Compromise resolved a conflict over counting actual human beings for political and financial advantage, with those human beings having no voice in the outcome — a fundamentally different kind of compromise involving actual injustice, not just competing state interests.'),
  ('Explain what "direct taxes" refers to in Source B, and why Southern states\' position on counting enslaved people for taxation might seem surprising at first.', 'Direct taxes were federal taxes owed by each state, calculated in part using population; it might seem surprising that Southern states, who wanted enslaved people counted for representation, did not also want them counted for taxation — but their position was consistently about maximizing power while minimizing cost to their states, not about any single fixed formula.'),
  ('Write a two-to-three sentence evaluation of the Great Compromise: what did it successfully solve, and what tension (if any) do you think it may have left unresolved for the future?', 'Answers vary; must credit the Great Compromise with resolving the large-state/small-state representation deadlock, and may note ongoing tension over how well the Senate\'s equal-representation structure serves a nation with vastly different state populations, then and now.'),
  ('Write a two-to-three sentence evaluation of the Three-Fifths Compromise using the vocabulary term "tradeoff." Whose tradeoff was it, and whose was it not?', 'Answers vary; must correctly use "tradeoff" to describe how Northern and Southern state delegates traded political and financial advantage against each other, while explicitly noting that enslaved people themselves had no say in or benefit from that tradeoff at all.'),
  ('Using both sources, write a short paragraph (4-5 sentences) explaining how the convention "solved" its representation problems through compromise, and evaluate whether "solved" is the right word for both compromises.', 'Answers vary; must summarize both compromises accurately and offer a reasoned evaluation — likely noting the Great Compromise genuinely resolved its specific structural conflict, while the Three-Fifths Compromise "resolved" the delegates\' political conflict but did not resolve, and in fact entrenched, a deep moral and human injustice.'),
  ('Explain why historians describe the Constitution produced by this convention as a document built on compromise rather than consensus.', 'Neither large vs. small states nor North vs. South ever fully agreed on a single shared principle; instead, each conflict was resolved through a negotiated middle position (two chambers; a fractional count) that let delegates with opposing interests accept a document none of them considered ideal, rather than one built on genuine shared agreement.'),
  ('Self-assessment: which compromise do you feel you can explain more confidently — the Great Compromise or the Three-Fifths Compromise — and which specific detail do you want to review again?', 'Answers vary; must name one compromise and one specific detail (e.g., the exact vote count, the formula\'s application to both representation and taxation) for review.')],
 '90-minute session',
 800,
 vocab=[
   ('Virginia Plan', 'proposed representation in Congress based on state population'),
   ('New Jersey Plan', 'proposed equal representation per state regardless of population'),
   ('Great Compromise', 'created a bicameral Congress: House by population, Senate equal'),
   ('Three-Fifths Compromise', 'counted each enslaved person as 3/5 for representation and taxation'),
   ('bicameral', 'a legislature with two separate chambers'),
   ('direct tax', 'a federal tax calculated in part using state population'),
 ],
 pacing='Warm-up 8 min · read both sources + vocabulary 15 min · guided compromise-comparison organizer 18 min · partner evaluation discussion 18 min · independent practice 22 min · extension work 5 min · assessment 4 min.')

# ------------------------------------------------------------------ Statistics
add('statistics101-polling', 'Statistics 101: Margin of Error in Polling — A Full Data-Analysis Session', 'Statistics', 'Statistics',
 'COURSE-OBJ.STAT101.2',
 'Interpret a poll\'s margin of error and confidence interval, and determine whether two poll results are statistically distinguishable or within expected sampling variation.',
 'Interpret margin of error and confidence intervals correctly, and determine whether an apparent change between two polls reflects a real shift or ordinary sampling variation.',
 'A poll surveys a sample, not the whole population, so its result carries sampling error. A 95% confidence interval (candidate support ± margin of error) means: if the same polling method were repeated many times, about 95% of the resulting intervals would contain the true population value. Margin of error shrinks as sample size grows, roughly proportional to 1/√n, so quadrupling the sample only halves the margin of error. Two poll results are statistically distinguishable only when their confidence intervals do not substantially overlap; a shift smaller than the combined margin of error may simply be sampling noise, not a real change in opinion.',
 [('Reading a single poll result', 'A poll of 1,000 voters shows Candidate A at 52%, margin of error ±3 points. The true population support is estimated to fall between 49% and 55% about 95% of the time this method is used — not "exactly 52%."'),
  ('Comparing two polls for a real change', 'Poll 1: Candidate A at 50% (±3). Poll 2, two weeks later: Candidate A at 53% (±3). The intervals (47-53) and (50-56) overlap substantially, so this 3-point shift is within expected sampling variation, not strong evidence of a real change.')],
 [('Poll A: The City Council Race, Six Weeks Out', (
   'A local newspaper commissions a poll of the city council race between incumbent Dana Reyes and challenger Marcus Webb. The pollster randomly selects 800 registered voters likely to vote, using a mix of phone and text-message outreach to reduce the chance that any one group (for example, only landline users, who skew older) is overrepresented. The result: Reyes 47%, Webb 44%, undecided 9%, with a stated margin of error of ±3.5 percentage points at a 95% confidence level.\n\n'
   'The newspaper\'s headline reads "Reyes Leads Webb by 3 Points," but the paper\'s data editor pushes back before publication. Reyes\'s true support could reasonably be anywhere from about 43.5% to 50.5%, and Webb\'s from about 40.5% to 47.5% — the two ranges overlap substantially, roughly from 43.5% to 47.5%. That overlap means the poll cannot rule out the possibility that Webb is actually ahead, or that the race is exactly tied. The editor revises the headline to "Reyes Narrowly Ahead of Webb, Race Within Margin of Error" instead, a smaller but more accurate claim than "leads."')),
  ('Poll B: A Follow-Up Poll Two Weeks Later', (
   'Two weeks before the election, the same newspaper commissions a second poll, this time surveying 1,600 likely voters — double the first poll\'s sample size — using the same phone-and-text methodology. The result: Reyes 49%, Webb 42%, undecided 9%, with a stated margin of error of ±2.5 percentage points.\n\n'
   'A reporter drafts a story claiming "Reyes\'s Lead Has Widened From 3 Points to 7 Points," treating the shift from Poll A to Poll B as clear evidence that Reyes gained ground. The data editor again intervenes: doubling the sample size reduced the margin of error, but not proportionally — from ±3.5 to ±2.5, not to ±1.75, because margin of error shrinks with the square root of sample size, not sample size directly. More importantly, Reyes\'s confidence interval in Poll B (46.5% to 51.5%) barely overlaps Poll A\'s interval (43.5% to 50.5%) at the very top, while Webb\'s interval in Poll B (39.5% to 44.5%) does not overlap Poll A\'s interval (40.5% to 47.5%) by much either. The editor concludes this pattern is more consistent with a real shift toward Reyes than the first comparison would have been, but still asks the reporter to describe the change as "an apparent gain for Reyes, though within the range sampling variation alone could produce" rather than stating it as certain.'))],
 [('What does "±3.5 percentage points at a 95% confidence level" mean, using the lesson\'s own definition?', 'If the same polling method were repeated many times, about 95% of the resulting margin-of-error intervals would contain the true population value; it does not mean the reported number is exactly correct.'),
  ('Calculate Reyes\'s full confidence interval in Poll A, showing your addition and subtraction.', '47% - 3.5% = 43.5%; 47% + 3.5% = 50.5%. Reyes\'s interval is 43.5% to 50.5%.'),
  ('Calculate Webb\'s full confidence interval in Poll A.', '44% - 3.5% = 40.5%; 44% + 3.5% = 47.5%. Webb\'s interval is 40.5% to 47.5%.'),
  ('Why did the data editor reject the original "Reyes Leads Webb by 3 Points" headline for Poll A?', 'Because Reyes\'s and Webb\'s confidence intervals overlap substantially (roughly 43.5% to 47.5%), the poll cannot rule out Webb actually being ahead or the race being tied, so "leads" overstates the certainty the data supports.'),
  ('Explain why doubling the sample size from 800 to 1,600 did not cut the margin of error in half.', 'Margin of error is roughly proportional to 1/√n (one over the square root of the sample size), not 1/n; since √2 is about 1.41, not 2, doubling the sample size only reduces the margin of error by a factor of about 1.41, not 2 — consistent with the drop from ±3.5 to ±2.5 rather than to ±1.75.'),
  ('Calculate Reyes\'s and Webb\'s confidence intervals in Poll B, showing your work.', 'Reyes: 49% - 2.5% = 46.5%; 49% + 2.5% = 51.5%, so 46.5% to 51.5%. Webb: 42% - 2.5% = 39.5%; 42% + 2.5% = 44.5%, so 39.5% to 44.5%.'),
  ('With a partner, compare Reyes\'s intervals across both polls (43.5-50.5 in Poll A; 46.5-51.5 in Poll B). Explain in your own words why the data editor sees this as weak evidence of a real gain rather than strong proof.', 'The two intervals only barely overlap at the top (around 46.5-50.5), which is more consistent with a real shift than a large overlap would be, but the overlap is not zero, so ordinary sampling variation between two separately drawn samples still cannot be fully ruled out as the explanation.'),
  ('With a partner, discuss: why does the lesson describe the phone-and-text outreach method as reducing the chance that "any one group is overrepresented"? What could go wrong with a phone-only poll?', 'A phone-only poll (especially landline-only) could overrepresent groups more likely to have and answer landlines, such as older voters, producing a sample that does not accurately reflect the full population of likely voters — a form of sampling bias distinct from margin of error.'),
  ('Discuss: the reporter wanted to say Reyes\'s "lead widened from 3 points to 7 points." Explain what is misleading about treating the raw point totals (47-44=3 vs. 49-42=7) as the full story.', 'The raw point gap ignores the margin of error on each poll; a gap can grow numerically between two polls without that growth being statistically meaningful, since each individual poll result already carries several points of uncertainty in either direction.'),
  ('Why does the lesson say a poll surveys "a sample, not the whole population"? What is the practical consequence of this for any single poll number?', 'Because interviewing every voter is impractical, pollsters interview a subset and use it to estimate the whole population\'s views; the practical consequence is that any single reported number is an estimate with built-in uncertainty (the margin of error), not an exact measurement.'),
  ('A classmate says "a 1,600-person poll is always better than an 800-person poll." Evaluate this claim using evidence from the lesson.', 'A larger sample does reduce margin of error (as shown going from Poll A to Poll B), so it is generally more precise, but the claim is incomplete: sample size alone does not fix sampling bias from a flawed method (e.g., a non-representative outreach method), so a larger biased sample can still be worse than a smaller, well-designed one.'),
  ('Explain, using the definition of "statistically distinguishable" from the lesson, why Poll 1 vs. Poll 2 in the Model 2 example (50% ±3 vs. 53% ±3) was called "not strong evidence of a real change."', 'The two confidence intervals (47-53 and 50-56) overlap substantially, so the 3-point shift falls well within what ordinary sampling variation between two separate samples could produce, meaning the poll cannot confidently distinguish a real opinion shift from noise.'),
  ('Design an original two-poll scenario (with made-up but plausible numbers and margins of error) where the shift between polls IS statistically distinguishable. Explain why using interval math.', 'Answers vary; must show two confidence intervals that do not overlap (or barely overlap), with the numbers/margins explicitly stated and the non-overlap explained as evidence the shift is unlikely to be pure sampling noise.'),
  ('Design an original two-poll scenario where the shift is NOT statistically distinguishable, and explain why.', 'Answers vary; must show two confidence intervals that substantially overlap, with the shift explained as plausibly explainable by sampling variation alone.'),
  ('Explain what "undecided" voters (9% in both polls) mean for interpreting the race, beyond the margin-of-error math.', 'Undecided voters represent voters whose eventual choice is not yet captured by either candidate\'s percentage; with a 5-point-or-smaller gap between candidates and 9% undecided, the undecided bloc alone could be large enough to decide the race regardless of the current margin-of-error analysis.'),
  ('Write a two-to-three sentence, accurate headline for Poll B\'s results that a careful data editor would approve, using the lesson\'s cautious framing as a model.', 'Answers vary; must avoid overstating certainty (no "clear lead" or "widening lead" claimed as fact) and should reflect that the shift is an apparent, not confirmed, change, similar to "Reyes Shows Modest Gain Over Webb, Though Race Remains Close" or similar appropriately hedged language.'),
  ('Explain why a pollster reports a margin of error at all, instead of just reporting the single percentage (e.g., "47%") as the answer.', 'Reporting only the raw percentage without the margin of error would falsely imply the number is exact; the margin of error communicates the real uncertainty inherent in estimating a full population\'s views from a sample, which is essential for readers to interpret the result correctly.'),
  ('Compare the two case files: what specific methodological choice stayed the same between Poll A and Poll B, and what changed? Why does this matter for comparing them fairly?', 'The phone-and-text outreach methodology stayed the same; the sample size changed (800 to 1,600). Keeping the method constant while changing sample size makes the comparison fairer, since a change in results is less likely to be explained by a change in methodology rather than a real or sampling-driven shift.'),
  ('Write a short paragraph (4-5 sentences) explaining to a non-statistics friend why "Reyes leads by 3 points" and "the race is within the margin of error" can both be defensible ways to describe the exact same Poll A data.', 'Answers vary; must explain that the raw numbers do show Reyes ahead by 3 points, but the margin of error means the true difference could be zero or even reversed, so a cautious/complete description accounts for both facts rather than only reporting the headline number.'),
  ('Self-assessment: which is harder for you right now — calculating a confidence interval, or explaining in words why two overlapping intervals are not strong evidence of a real change? Name one specific thing you would review.', 'Answers vary; must name a specific skill from the lesson (interval calculation or interval-overlap interpretation) and one concrete thing to review.')],
 '90-minute session',
 800,
 vocab=[
   ('sample', 'a subset of a population surveyed to estimate the whole'),
   ('margin of error', 'the range of likely error around a poll estimate'),
   ('confidence interval', 'estimate ± margin of error, at a stated confidence level'),
   ('sampling bias', 'a flawed method that skews who gets surveyed'),
   ('statistically distinguishable', 'two results whose intervals do not substantially overlap'),
   ('sampling variation', 'natural result-to-result differences from chance alone'),
 ],
 pacing='Warm-up 8 min · read both poll case files + vocabulary 15 min · guided interval-calculation organizer 18 min · partner comparison discussion 18 min · independent practice 22 min · extension work 5 min · assessment 4 min.')

# -------------------------------------------------------------------- Chemistry
add('chemistry101-stoichiometry', 'Chemistry 101: Stoichiometry in the Lab — A Full Limiting-Reactant Session', 'Chemistry 101', 'Chemistry',
 'COURSE-OBJ.CHEM101.2',
 'Balance chemical equations, identify the limiting reactant given starting masses, and calculate theoretical and percent yield from lab data.',
 'Balance equations, identify a limiting reactant from given masses, and calculate theoretical and percent yield, applying each step to real lab data.',
 'A balanced equation shows the mole ratio in which reactants combine and products form; coefficients must be adjusted so the same number of each atom appears on both sides. Given starting masses, converting each reactant to moles and comparing to the balanced ratio identifies the limiting reactant — the one that runs out first and caps how much product can form; any reactant left over is in excess. Theoretical yield is the maximum product mass calculable from the limiting reactant; percent yield compares the mass actually collected in the lab to that theoretical maximum, and is always reported below 100% due to real losses (transfer, side reactions, purification).',
 [('Balancing an equation', 'Unbalanced: Fe + O2 -> Fe2O3. Balanced: 4Fe + 3O2 -> 2Fe2O3. Check: 4 Fe atoms and 6 O atoms appear on both sides.'),
  ('Finding the limiting reactant', 'Given 2.0 mol H2 and 2.0 mol O2 for 2H2 + O2 -> 2H2O (a 2:1 ratio needed): 2.0 mol H2 needs only 1.0 mol O2, so O2 is in excess and H2 is the limiting reactant.')],
 [('Lab Notebook, Part 1: Balancing and Planning the Reaction', (
   'Today\'s lab produces copper(II) hydroxide by reacting copper(II) sulfate with sodium hydroxide in solution: CuSO4 + NaOH -> Cu(OH)2 + Na2SO4. Before touching any chemicals, every student must balance this equation and use it to plan exactly how much of each reactant the lab requires.\n\n'
   'Working through it: one copper, one sulfate, so those stay balanced with a coefficient of 1 on CuSO4 and Na2SO4. But sodium and hydroxide each need a coefficient of 2 to balance the two sodium atoms and two hydroxide groups on the product side: CuSO4 + 2NaOH -> Cu(OH)2 + Na2SO4. Checking every atom: 1 Cu, 1 S, 4 O (from sulfate) + 2 O (from hydroxide) = 6 O total on the left; on the right, 1 Cu, 2 O + 2 H (from Cu(OH)2), plus 2 Na, 1 S, 4 O (from sulfate) — all atoms match once every O is counted carefully.\n\n'
   'Today\'s planned amounts: 0.0500 mol CuSO4 and 0.0800 mol NaOH. The balanced equation requires NaOH at twice the moles of CuSO4 (a 1:2 ratio) for a perfect, no-leftover reaction. Students are asked to determine, before mixing anything, which reactant will run out first at these specific starting amounts.')),
  ('Lab Notebook, Part 2: Measuring Yield', (
   'After calculating that CuSO4 was the limiting reactant (0.0500 mol CuSO4 would need 0.1000 mol NaOH to fully react, but only 0.0800 mol NaOH was available — wait, students are asked to check this calculation carefully against the ratio, since it determines everything that follows), the lab groups proceed to run the reaction, filtering out the solid copper(II) hydroxide precipitate that forms.\n\n'
   'Using the limiting reactant\'s moles and the 1:1 mole ratio between CuSO4 and Cu(OH)2 in the balanced equation, each group calculates a theoretical yield: the maximum possible mass of Cu(OH)2 the reaction could produce if every bit of the limiting reactant converted perfectly, with nothing lost. Cu(OH)2 has a molar mass of 97.57 g/mol.\n\n'
   'After filtering, drying, and weighing their actual product, Group 3 collects 3.62 grams of Cu(OH)2. Group 7, running the identical planned reaction, collects only 3.05 grams. Both groups are asked to calculate their percent yield and explain, using specific possible lab errors, why two groups running the same planned reaction might collect different actual masses even though their theoretical yield calculation should be identical.'))],
 [('Balance this equation and show your reasoning: Fe + O2 -> Fe2O3.', '4Fe + 3O2 -> 2Fe2O3. Reasoning: balancing Fe2O3 requires an even number of Fe, so start with 2Fe2O3, giving 4 Fe and 6 O on the right, which requires 4Fe and 3O2 on the left.'),
  ('In the lab\'s balanced equation CuSO4 + 2NaOH -> Cu(OH)2 + Na2SO4, what mole ratio of NaOH to CuSO4 is required for a perfect, no-leftover reaction?', '2:1 (NaOH to CuSO4) — every 1 mole of CuSO4 requires 2 moles of NaOH.'),
  ('Using the planned amounts (0.0500 mol CuSO4, 0.0800 mol NaOH), calculate how much NaOH would be needed to fully react with all the CuSO4, and compare it to what is actually available.', '0.0500 mol CuSO4 × 2 = 0.1000 mol NaOH needed; only 0.0800 mol NaOH is available, which is less than needed.'),
  ('Based on the previous calculation, identify the limiting reactant and explain your reasoning in a full sentence.', 'NaOH is the limiting reactant, because the reaction needs 0.1000 mol of it to fully react with the available CuSO4, but only 0.0800 mol is present — NaOH will run out first.'),
  ('The lab notebook text initially assumes CuSO4 is limiting; explain what error this represents and why checking the calculation carefully matters.', 'This is the same error as jumping to a conclusion without doing the mole-ratio comparison; the actual calculation shows NaOH, not CuSO4, runs out first, which reverses which reactant\'s moles must be used for every later yield calculation — getting this step wrong invalidates the rest of the analysis.'),
  ('Using the correct limiting reactant and the balanced equation\'s mole ratio, calculate the moles of Cu(OH)2 theoretically produced.', 'The limiting reactant is NaOH at 0.0800 mol; the ratio of NaOH to Cu(OH)2 is 2:1, so 0.0800 mol NaOH ÷ 2 = 0.0400 mol Cu(OH)2 theoretically produced.'),
  ('With a partner, calculate the theoretical yield in grams using the molar mass given (97.57 g/mol), showing your unit conversion.', '0.0400 mol Cu(OH)2 × 97.57 g/mol = 3.9028 g, or about 3.90 g theoretical yield.'),
  ('With a partner, calculate Group 3\'s percent yield (actual 3.62 g) and Group 7\'s percent yield (actual 3.05 g), showing the percent-yield formula used.', 'Percent yield = (actual ÷ theoretical) × 100. Group 3: (3.62 ÷ 3.90) × 100 ≈ 92.8%. Group 7: (3.05 ÷ 3.90) × 100 ≈ 78.2%.'),
  ('Discuss: why does the lesson say percent yield is "always reported below 100%"? Is a percent yield over 100% possible, and what would it suggest if reported?', 'Real reactions lose some product to transfer, side reactions, or incomplete purification, so 100% recovery is essentially never achieved; a reported yield over 100% would suggest a measurement or purity error (e.g., the product still contains water or leftover reactant adding extra mass), not a genuinely more-than-complete reaction.'),
  ('Propose two specific, different lab errors that could explain why Group 7\'s yield (78.2%) was lower than Group 3\'s (92.8%), given they ran the identical planned reaction.', 'Answers vary; must propose two specific, plausible causes, e.g., some precipitate lost during filtering (stuck to filter paper or lost in transfer), incomplete drying leaving residual water weighed as part of the "dry" product (which would raise, not lower, apparent yield — so likely product loss instead), or a measurement error in reactant amounts before mixing.'),
  ('Explain, using the definition of excess reactant, what happens to the leftover NaOH or CuSO4 (whichever is not limiting) in this reaction.', 'The excess reactant does not fully react; some of it remains unreacted in the mixture after the limiting reactant is used up, since there isn\'t enough of the limiting reactant to consume all of the excess reactant.'),
  ('Calculate how many moles of the excess reactant remain unreacted after the reaction goes to completion.', 'CuSO4 needed to react with 0.0800 mol NaOH = 0.0800 ÷ 2 = 0.0400 mol CuSO4 consumed; starting CuSO4 was 0.0500 mol, so 0.0500 - 0.0400 = 0.0100 mol CuSO4 remains unreacted (excess).'),
  ('If a student mistakenly used CuSO4 (the excess reactant) instead of NaOH to calculate theoretical yield, would their theoretical yield be too high or too low? Explain your reasoning.', 'Too high — using CuSO4\'s full 0.0500 mol (instead of the smaller, correctly limiting NaOH-derived 0.0400 mol) would produce a larger, incorrect theoretical yield, since it assumes a reactant is available in an amount it is not able to actually be converted to product given the true limiting reactant.'),
  ('Explain why chemists check that every atom balances on both sides of an equation, using a specific atom count from the copper hydroxide equation as evidence.', 'The law of conservation of mass requires that atoms are neither created nor destroyed in a chemical reaction, only rearranged; checking, for example, that 6 oxygen atoms appear on both sides of CuSO4 + 2NaOH -> Cu(OH)2 + Na2SO4 confirms the equation obeys this law and accurately represents what actually happens.'),
  ('Design an original limiting-reactant scenario (different reactants, different starting moles) and identify which reactant is limiting, showing your ratio comparison.', 'Answers vary; must state a balanced equation\'s mole ratio, give specific starting moles for two reactants, and correctly identify the limiting reactant using a ratio comparison consistent with the given numbers.'),
  ('Using your scenario from the previous question, calculate the theoretical yield of product in moles.', 'Answers vary; must correctly apply the mole ratio between the limiting reactant and the product from the student\'s own balanced equation.'),
  ('Write a two-to-three sentence lab-report explanation (in your own words) of why two groups running the "same" planned reaction can reasonably report different percent yields, without implying either group made a scientific error.', 'Answers vary; must reflect that some product loss during transfer/filtering/drying is a normal, expected part of real lab technique and does not by itself indicate the reaction or the underlying chemistry was done incorrectly.'),
  ('Compare theoretical yield and percent yield: what does each one tell you, and why do chemists need both numbers rather than just one?', 'Theoretical yield tells you the maximum possible product mass a reaction could produce under ideal conditions; percent yield tells you how efficiently the actual lab procedure captured that maximum. Both are needed because percent yield alone (without a theoretical yield benchmark) would have no basis for comparison, and theoretical yield alone does not reflect real lab performance.'),
  ('Explain why molar mass (97.57 g/mol for Cu(OH)2) is needed as a conversion factor, and what two units it connects.', 'Molar mass connects grams and moles; since lab balances measure mass but the balanced-equation mole ratio works in moles, molar mass is the conversion factor needed to move between the two units in either direction.'),
  ('Self-assessment: rate your confidence in identifying a limiting reactant from starting moles, and name one specific step in the process you want to practice again.', 'Answers vary; must name a specific step from the process (e.g., converting to moles, applying the mole ratio, comparing the two reactants) to revisit.')],
 '90-minute session',
 800,
 vocab=[
   ('balanced equation', 'an equation with equal atoms of each element on both sides'),
   ('mole ratio', 'the ratio of moles of substances in a balanced equation'),
   ('limiting reactant', 'the reactant that runs out first and caps product formed'),
   ('excess reactant', 'the reactant left over after the reaction completes'),
   ('theoretical yield', 'the maximum possible product mass from the limiting reactant'),
   ('percent yield', 'actual yield divided by theoretical yield, times 100'),
 ],
 pacing='Warm-up 8 min · read both lab notebook passages + vocabulary 15 min · guided limiting-reactant organizer 18 min · partner yield-calculation discussion 18 min · independent practice 22 min · extension work 5 min · assessment 4 min.')

# -------------------------------------------------------------------- Sociology
add('sociology101-institutions', 'Sociology 101: Social Institutions in Practice — A Full Case-Comparison Session', 'Sociology 101', 'Sociology',
 'COURSE-OBJ.SOC101.2',
 'Apply the sociological concepts of social institutions, norms, and social capital to compare how two different communities respond to the same disruption.',
 'Apply core sociological concepts (social institution, norm, social capital) to analyze and compare how two real-feeling communities respond to the same type of disruption.',
 'A social institution is an established, patterned set of practices organized around a core social need — family, education, religion, government, and the economy are classic examples. Norms are shared expectations for behavior within a group, enforced through informal reactions (a raised eyebrow) or formal rules (a law). Social capital refers to the networks of relationships and mutual trust that let people and communities get things done together; it is distinct from financial capital, since two communities with similar incomes can have very different levels of it. Sociologists often compare communities responding to the same type of event (a flood, plant closure, or crisis) to see how existing institutions, norms, and social capital shape different outcomes even under similar pressure.',
 [('Identifying a social institution in action', 'When a town\'s volunteer fire department organizes a fundraiser after a family loses their home to fire, "volunteer fire department" and "neighborhood fundraising" both function as institutions — patterned, expected community responses, not one-time individual actions.'),
  ('Distinguishing social capital from financial capital', 'Two neighborhoods each raise $2,000 after a similar loss. In Neighborhood A, the money came from 200 small individual donations coordinated through existing community group texts. In Neighborhood B, it came from one wealthy donor. Both raised the same amount, but Neighborhood A shows more social capital — a dense network capable of coordinating collective action.')],
 [('Case File 1: Riverbend After the Flood', (
   'When the river overflowed its banks last spring, Riverbend lost power for four days and saw four blocks of homes flooded. Within hours, the town\'s existing institutions activated in familiar, patterned ways: the volunteer fire department, already organized and equipped, went door to door checking on elderly residents; the two churches on Main Street, which had coordinated a joint food pantry for a decade, opened their doors as emergency shelters without needing new instructions; and the parent-teacher association, which normally organizes school fundraisers, redirected its existing phone tree and group chat to coordinate donated clothing and supplies within a single afternoon.\n\n'
   'A sociologist studying the recovery later noted that Riverbend\'s response was fast not because any single organization was unusually well-funded, but because its residents had pre-existing, trusted relationships across several institutions at once — the fire department volunteers were often also church members and PTA parents, meaning information and resources moved through overlapping networks instead of starting from scratch. Within three weeks, informal norms also shifted: neighbors who previously kept spare keys only for close friends began routinely offering them to more distant neighbors "just in case," a new, lasting norm the town had not had before the flood.')),
  ('Case File 2: Millbrook After the Flood', (
   'The same storm system flooded Millbrook, a town of similar size about forty miles away, with comparable property damage. But Millbrook\'s recovery looked different. The town had no volunteer fire department — fire and emergency response were contracted out to a regional company based two counties away, and while professionally competent, the crews had no pre-existing relationships with Millbrook residents and left once immediate danger had passed. Millbrook\'s three churches did not have a history of coordinating with each other, and each opened separately, duplicating some efforts (two shelters within a block of each other) while leaving other needs, like transportation for elderly residents without cars, unaddressed by any institution.\n\n'
   'Millbrook did eventually recover, but more slowly: it took closer to six weeks for donated supplies to be efficiently distributed, partly because no single existing network had the trust and reach to coordinate across the town\'s separate institutions quickly. A local sociologist observed that Millbrook was not poorer than Riverbend, and its individual institutions (the churches, the school) were each reasonably resourced — what differed was the density of overlapping relationships connecting those institutions to each other, which is to say, its stock of social capital.'))],
 [('Define "social institution" using the lesson\'s definition, then name two examples from Case File 1.', 'A social institution is an established, patterned set of practices organized around a core social need; examples from Case File 1 include the volunteer fire department, the churches\' food pantry/shelter coordination, and the PTA\'s phone tree.'),
  ('What new norm developed in Riverbend after the flood, and how does it fit the lesson\'s definition of a norm?', 'Neighbors began routinely offering spare keys to more distant neighbors "just in case" — this fits the definition of a norm because it became a shared, patterned expectation of behavior within the community that had not existed before.'),
  ('Explain why the sociologist in Case File 1 says Riverbend\'s fast response was not mainly about funding.', 'The sociologist attributes the speed to pre-existing, overlapping trusted relationships across institutions (the same people being fire volunteers, church members, and PTA parents), not to any institution having unusually large financial resources.'),
  ('Identify one specific institution in Millbrook that functioned differently than its counterpart in Riverbend, and explain the difference.', 'The fire/emergency response: Riverbend had a local volunteer department with pre-existing relationships to residents; Millbrook contracted out to a regional company with no pre-existing local relationships, which left once immediate danger passed.'),
  ('What specific problem did Millbrook\'s three separate, uncoordinated churches cause, according to the case file?', 'They duplicated some efforts (two shelters within a block of each other) while leaving other needs, like transportation for elderly residents without cars, unaddressed by any institution.'),
  ('Using the lesson\'s definition, explain why the sociologist calls the difference between Riverbend and Millbrook a difference in "social capital" rather than financial capital.', 'The sociologist explicitly says Millbrook was not poorer than Riverbend and its individual institutions were reasonably resourced; what differed was the density of overlapping relationships connecting institutions to each other, which is what the lesson defines as social capital, distinct from financial resources.'),
  ('With a partner, discuss: in Model 2 (the $2,000 fundraiser example), why does the lesson call Neighborhood A\'s outcome a stronger example of social capital even though both neighborhoods raised the same amount?', 'Neighborhood A\'s funds came from 200 coordinated small donations through existing community networks, demonstrating a dense, functioning network capable of collective action; Neighborhood B\'s single large donation does not demonstrate the same network capacity, even though the financial outcome was identical.'),
  ('With a partner, identify one institution in your own community (real or realistic) and describe one norm associated with it.', 'Answers vary; must name a genuine or realistic institution (school, place of worship, local government, workplace) and a specific associated norm (an expected behavior within that institution).'),
  ('Discuss: the lesson says norms are enforced "informally" or "formally." Give one informal and one formal example of norm enforcement from either case file or your own knowledge.', 'Answers vary; must correctly distinguish informal enforcement (social disapproval, a raised eyebrow, gossip) from formal enforcement (a written rule, a law, an official consequence), using a real or realistic example.'),
  ('Predict what might happen if Riverbend experienced a second, unrelated crisis (e.g., a job-loss wave) one year after the flood. Use evidence from Case File 1 to justify your prediction.', 'Riverbend would likely respond relatively effectively again, since the case file shows its overlapping institutional networks and trust-based norms (like the new key-sharing norm) persisted and are not flood-specific, suggesting the underlying social capital could be mobilized for a different kind of disruption too.'),
  ('Propose one specific, realistic change Millbrook could make to build more social capital between its institutions before the next crisis.', 'Answers vary; must propose a specific, plausible mechanism for building overlapping relationships between institutions, e.g., the three churches establishing a joint coordination committee, or the school inviting emergency responders to regular community events.'),
  ('Explain the relationship between "overlapping networks" (people who are fire volunteers AND church members AND PTA parents) and the speed of Riverbend\'s recovery, using the case file\'s own reasoning.', 'Because the same individuals belonged to multiple institutions at once, information and resources could move directly through personal trust relationships across institutional lines instead of each institution having to coordinate from scratch with unfamiliar counterparts — this is what let Riverbend act quickly and cohesively.'),
  ('A classmate claims "Millbrook\'s problem was that its churches and schools were badly run." Evaluate this claim using evidence from Case File 2.', 'The case file explicitly states Millbrook\'s individual institutions were "each reasonably resourced," so the claim is not well supported; the actual problem identified was the lack of coordination and overlapping relationships between institutions, not poor management of any single one.'),
  ('Write a two-to-three sentence comparison of Riverbend and Millbrook that uses all three vocabulary terms (institution, norm, social capital) correctly.', 'Answers vary; must use all three terms accurately in a coherent comparison of the two towns\' flood responses.'),
  ('Design an original short scenario (not a flood) showing how social capital could speed or slow a community\'s response to a different type of disruption (e.g., a factory closing, a school redistricting).', 'Answers vary; must describe a specific disruption and explain how the presence or absence of overlapping institutional relationships plausibly affects the community\'s response, using the lesson\'s logic.'),
  ('Explain why a sociologist would study two similar towns experiencing the same disruption, rather than studying just one town in isolation.', 'Comparing two similar cases responding to the same type of event helps isolate what actually explains the difference in outcomes (in this case, social capital) by holding other factors (the type of disruption, town size, general resource level) roughly constant.'),
  ('Identify one limitation of this two-case comparison: what is one factor, other than social capital, that could also explain the different recovery speeds?', 'Answers vary; must propose a plausible alternative or confounding factor, e.g., differences in the severity or exact timing of flooding, differences in local government resources, or differences in how many days each town had advance warning.'),
  ('Write a short paragraph (4-5 sentences) explaining, in your own words, why sociologists distinguish "social capital" as its own concept separate from wealth or income.', 'Answers vary; must explain that financial resources and network/trust resources are distinct kinds of capital that can vary independently, and that both can meaningfully shape outcomes like disaster recovery, sometimes with network capital mattering as much as or more than money.'),
  ('Explain how the PTA\'s "existing phone tree and group chat" in Riverbend is itself an example of social capital being put to a new use.', 'The phone tree and group chat were built for routine school fundraising, but because they represented an already-trusted, functioning communication network, that same network could be redirected almost instantly to flood relief — showing how existing social capital transfers to new purposes rather than needing to be rebuilt each time.'),
  ('Self-assessment: which of the three vocabulary terms (institution, norm, social capital) do you feel you could explain most confidently to someone outside class, and which needs more review?', 'Answers vary; must name one term for each part with a genuine reason.')],
 '90-minute session',
 800,
 vocab=[
   ('social institution', 'an established, patterned set of practices around a core need'),
   ('norm', 'a shared expectation for behavior within a group'),
   ('social capital', 'networks of relationships and trust that enable collective action'),
   ('formal enforcement', 'a written rule or official consequence for a norm violation'),
   ('informal enforcement', 'social disapproval or reaction, not an official rule'),
   ('overlapping network', 'the same individuals connecting multiple institutions at once'),
 ],
 pacing='Warm-up 8 min · read both case files + vocabulary 15 min · guided institution/norm organizer 18 min · partner comparison discussion 18 min · independent practice 22 min · extension work 5 min · assessment 4 min.')

# --------------------------------------------------------------- Philosophy/Ethics
add('ethics101-frameworks', 'Philosophy 101: Ethical Frameworks in Practice — A Full Applied-Ethics Session', 'Philosophy 101: Ethics', 'Philosophy',
 'COURSE-OBJ.PHIL101.2',
 'Apply utilitarian and deontological ethical frameworks to the same original case, and evaluate where the two frameworks agree and where they genuinely conflict.',
 'Apply utilitarian and deontological reasoning accurately to real cases, and identify precisely where the two frameworks agree or genuinely conflict.',
 'Utilitarianism judges an action by its consequences: the right action is the one producing the greatest total well-being (or least total harm) for everyone affected, aggregated across all people. Deontology judges an action by whether it follows a moral duty or rule, regardless of the consequences — some acts (like lying or breaking a promise) are held to be wrong even if they would produce a better outcome. The two frameworks often agree in ordinary cases, but diverge sharply when following a duty would produce a worse aggregate outcome than breaking it, or when maximizing total welfare would require treating one person merely as a means to benefit others.',
 [('Applying utilitarian reasoning', 'A city can spend its budget fixing one dangerous intersection (preventing an estimated 3 serious injuries/year) or repaving five miles of cracked sidewalk (preventing an estimated 12 minor injuries/year spread across more people). A strict utilitarian calculation compares total harm prevented, not just which option "feels" more urgent.'),
  ('Applying deontological reasoning', 'A doctor could save five patients by secretly harvesting organs from one healthy, unwilling visitor. A deontologist rejects this regardless of the favorable 5-vs-1 outcome, because it requires using a person as a mere means (without consent) and violates a duty not to kill — the outcome does not justify the rule violation.')],
 [('Case File 1: The Whistleblower\'s Dilemma', (
   'Amara works in quality control at a mid-sized auto-parts manufacturer. She discovers that a batch of brake components, already shipped to three dealerships, has a small but real defect rate — internal testing suggests about 1 in 4,000 units could fail under specific cold-weather conditions, potentially causing a crash. Amara\'s manager tells her the company has signed a strict non-disclosure agreement with the dealerships covering exactly this kind of internal testing data, and that going public would violate a legally binding promise, trigger a lawsuit that could bankrupt the company, and cost around 400 people their jobs — while a voluntary recall handled quietly, dealership by dealership, would fix the actual defect just as effectively without public disclosure.\n\n'
   'Amara has to decide whether to honor the non-disclosure agreement and trust the quiet recall process, or break her promise and go public immediately, on the theory that customers have a right to know about a safety risk regardless of the company\'s preferred process. She has no way to be completely certain the quiet recall will reach every affected vehicle before cold weather arrives.')),
  ('Case File 2: Two Students Analyze the Dilemma', (
   'Two philosophy students, Priya and Julian, are asked to analyze Amara\'s dilemma using the two frameworks from class.\n\n'
   'Priya applies utilitarian reasoning first: she estimates the total expected harm from staying quiet (a small chance of injury per defective unit, multiplied across thousands of units, factored against the quiet recall\'s effectiveness) against the total expected harm from going public immediately (400 job losses, a company bankruptcy affecting suppliers and their families, but faster and more certain awareness of the risk). Her tentative conclusion: if the quiet recall is genuinely reliable and fast, the aggregate expected harm from staying quiet and trusting the recall could be lower than the aggregate harm from an immediate public disclosure that bankrupts the company — but she notes this conclusion depends heavily on how reliable the quiet recall actually turns out to be, which Amara cannot fully verify in advance.\n\n'
   'Julian applies deontological reasoning: regardless of the aggregate outcome calculation, he argues Amara has a duty not to conceal a known safety risk from people who could be physically harmed by it, and that this duty does not bend based on how the numbers happen to work out. For Julian, the non-disclosure agreement cannot override a more fundamental duty to prevent foreseeable harm to third parties who never consented to that agreement in the first place — the dealerships signed it, not the customers who might be injured.\n\n'
   'Priya and Julian agree on one thing: Amara should not simply do nothing and hope for the best. But they reach that shared conclusion by fundamentally different reasoning paths.'))],
 [('Define utilitarianism using the lesson\'s own wording.', 'Utilitarianism judges an action by its consequences: the right action is the one producing the greatest total well-being (or least total harm) for everyone affected, aggregated across all people.'),
  ('Define deontology using the lesson\'s own wording.', 'Deontology judges an action by whether it follows a moral duty or rule, regardless of the consequences; some acts are held to be wrong even if they would produce a better outcome.'),
  ('In Model 2 (the organ-harvesting case), why does a deontologist reject the action even though it saves more lives (5) than it costs (1)?', 'Because it requires using a person as a mere means without their consent and violates a duty not to kill, which a deontologist holds is wrong regardless of the favorable numerical outcome.'),
  ('Summarize Priya\'s utilitarian analysis of Amara\'s dilemma in your own words, including what her conclusion depends on.', 'Priya compares the total expected harm of staying quiet (small injury risk across many units, reduced by a reliable recall) against going public (job losses, bankruptcy, supplier harm); her tentative conclusion that staying quiet could produce less aggregate harm depends heavily on how reliable the quiet recall actually turns out to be.'),
  ('Summarize Julian\'s deontological analysis in your own words.', 'Julian argues Amara has a duty not to conceal a known safety risk from people who could be harmed, and that this duty does not depend on the aggregate outcome calculation; the non-disclosure agreement, signed by the dealerships and not the customers, cannot override that duty.'),
  ('Identify the specific point in Case File 2 where Priya and Julian agree, and explain why they still count as using different frameworks despite this agreement.', 'They both agree Amara should not do nothing and hope for the best; they still count as using different frameworks because they reach that shared conclusion through different reasoning (aggregate-outcome calculation vs. duty-based reasoning), and their frameworks could have pointed in different directions under different numbers.'),
  ('With a partner, identify what specific new information would need to change for Priya\'s utilitarian conclusion to flip toward favoring immediate public disclosure.', 'If the quiet recall\'s reliability were lower than estimated (more defective units going unrepaired, or the recall being too slow for the coming cold season), the expected harm from staying quiet would rise, which could flip her aggregate calculation toward favoring public disclosure.'),
  ('With a partner, discuss: does Julian\'s deontological argument depend at all on how reliable the quiet recall turns out to be? Why or why not?', 'No — Julian\'s argument is explicitly framed as duty-based rather than outcome-based; the duty not to conceal a known safety risk applies whether or not the recall turns out to be reliable, which is precisely what distinguishes deontological from utilitarian reasoning.'),
  ('Discuss: is the non-disclosure agreement itself a "duty" in Julian\'s framework? Explain why or why not, using his own reasoning.', 'Julian treats it as a weaker or overridden duty rather than the governing one — he argues a more fundamental duty (not concealing foreseeable harm to non-consenting third parties) takes priority, and specifically notes the agreement was signed by dealerships, not by the customers at risk, which weakens its claim on Amara.'),
  ('Apply utilitarian reasoning to Model 1 (the city budget case): which project should the city choose, using only the numbers given, and show your comparison.', 'The sidewalk repaving prevents an estimated 12 minor injuries/year versus the intersection fix preventing 3 serious injuries/year; a strict utilitarian comparing total harm prevented would need to weigh severity, not just count, but using the numbers as a simple count-based estimate, the city should identify which option a rigorous aggregate-harm calculation favors and justify it, rather than choosing based on which "feels" more urgent.'),
  ('Explain why the lesson\'s Model 1 warns against choosing based on which option "feels more urgent."', 'A dramatic, single-location risk (one dangerous intersection) can feel more urgent than a diffuse, lower-severity risk spread across many people (cracked sidewalks), even if the aggregate harm calculation favors the less dramatic option — utilitarianism requires the actual total-harm comparison, not an intuitive urgency judgment.'),
  ('Design an original short ethical dilemma (not from this lesson) where utilitarian and deontological reasoning would likely reach different conclusions. Briefly explain why they diverge.', 'Answers vary; must present a scenario where following a rule/duty would produce a worse aggregate outcome than breaking it (or vice versa), and correctly explain the source of the divergence.'),
  ('Using your dilemma from the previous question, write one sentence of utilitarian reasoning and one sentence of deontological reasoning about it.', 'Answers vary; each sentence must correctly reflect its framework\'s reasoning style (aggregate outcome vs. duty/rule) as applied to the student\'s own scenario.'),
  ('A classmate claims "utilitarianism just means doing whatever benefits the most people, no matter what." Identify what is oversimplified about this claim, using the lesson\'s definition.', 'The lesson\'s definition specifies weighing total well-being or harm, not simply counting how many people benefit; a small benefit to many people is not automatically preferred over a large benefit or harm-avoidance for fewer people — utilitarianism requires an aggregate calculation, not a headcount.'),
  ('A classmate claims "deontology just means always telling the truth and always keeping promises, no exceptions." Identify what is oversimplified about this claim, using Julian\'s reasoning as evidence against it.', 'Julian\'s reasoning shows deontology can involve weighing competing duties (the duty to honor an agreement vs. the duty not to conceal foreseeable harm) rather than mechanically following one absolute rule; deontological reasoning can still be complex and can prioritize among duties, not just follow a single rule unconditionally.'),
  ('Explain why the dealerships\' agreement (not the customers\') matters to Julian\'s argument specifically, using the concept of consent.', 'Julian\'s objection relies partly on consent: the customers who could be physically harmed never agreed to the non-disclosure arrangement, so using their safety as leverage to honor a promise they were never party to is, in his view, a separate ethical problem from simply "breaking a promise."'),
  ('Write a short paragraph (4-5 sentences) giving your own reasoned position on what Amara should do, using at least one utilitarian and one deontological consideration explicitly.', 'Answers vary; must take a clear position and explicitly incorporate both an outcome-based (utilitarian) consideration and a duty-based (deontological) consideration in the reasoning, even if the final recommendation leans toward one framework.'),
  ('Explain one genuine strength and one genuine limitation of utilitarianism as an ethical framework, based on what this lesson\'s cases reveal.', 'Answers vary; a strength might be that it forces explicit comparison of real consequences rather than relying on intuition; a limitation might be that it can be used to justify serious harm to a minority (as in the organ-harvesting example) if the aggregate numbers favor it, or that it requires uncertain predictions (like recall reliability) that are hard to know in advance.'),
  ('Explain why Amara\'s uncertainty about the recall\'s reliability makes her decision harder under utilitarianism specifically, compared to under deontology.', 'Utilitarian reasoning depends on correctly predicting outcomes, so genuine uncertainty about the recall\'s reliability directly undermines confidence in the aggregate-harm calculation; deontological reasoning is comparatively less destabilized by this uncertainty, since the duty not to conceal a known risk applies whether or not the recall turns out to work well.'),
  ('Self-assessment: which framework do you find yourself naturally reasoning with more often in everyday life, and can you identify one specific decision (real or hypothetical) where you used it?', 'Answers vary; must identify one framework and connect it to a specific concrete decision or scenario, however small.')],
 '90-minute session',
 800,
 vocab=[
   ('utilitarianism', 'judging actions by total aggregate consequences'),
   ('deontology', 'judging actions by adherence to duty or rule'),
   ('aggregate harm/benefit', 'the total summed effect across everyone affected'),
   ('duty', 'a moral obligation that holds regardless of outcome'),
   ('means vs. end', 'using a person merely as a tool vs. respecting their own goals'),
   ('consent', 'a person\'s voluntary agreement, central to many duty-based objections'),
 ],
 pacing='Warm-up 8 min · read both case files + vocabulary 15 min · guided framework-comparison organizer 18 min · partner position discussion 18 min · independent practice 22 min · extension work 5 min · assessment 4 min.')

# ---------------------------------------------------------- Environmental Science
add('envsci101-watershed', 'Environmental Science 101: Nutrient Runoff and a Watershed — A Full Systems-Analysis Session', 'Environmental Science 101', 'Environmental Science',
 'COURSE-OBJ.ENVS101.2',
 'Trace how nutrient runoff moves through a watershed to cause eutrophication, and evaluate competing proposed interventions using cost, effectiveness, and tradeoff evidence.',
 'Explain the mechanism of nutrient-driven eutrophication in a watershed, and evaluate competing interventions using evidence about cost, effectiveness, and tradeoffs.',
 'A watershed is the land area that drains into a shared body of water; anything applied to that land (fertilizer, animal waste, sewage) can eventually reach the water through runoff. Excess nitrogen and phosphorus act as nutrients for algae, causing algal blooms. When the algae die, bacteria decomposing them consume dissolved oxygen, creating a hypoxic (low-oxygen) "dead zone" where fish and other aquatic life cannot survive — a process called eutrophication. Because a watershed integrates runoff from many sources across a large area, effective intervention usually requires addressing the sources contributing the most nutrient load, not just the most visible ones, and weighing cost against how much nutrient load each option actually removes.',
 [('Tracing the eutrophication mechanism', 'Fertilizer applied to a field is not fully absorbed by crops; rain carries the excess nitrogen and phosphorus into a stream, which feeds the lake. The added nutrients fuel an algal bloom; when the algae die and decompose, oxygen-consuming bacteria create a low-oxygen zone, killing fish that cannot leave the area in time.'),
  ('Comparing interventions by cost-effectiveness, not sticker price', 'Option A removes 2,000 lbs of nitrogen/year for $50,000 ($25/lb). Option B removes 500 lbs of nitrogen/year for $20,000 ($40/lb). Despite B\'s lower total cost, A removes more nitrogen per dollar spent — a more cost-effective choice if nitrogen reduction is the goal.')],
 [('Field Report, Part 1: Mapping the Sources in Lake Clearview\'s Watershed', (
   'Lake Clearview has experienced increasingly severe summer algal blooms over the past six years, with a major fish kill two summers ago traced to a hypoxic dead zone covering nearly a third of the lake. A team of environmental science students is assigned to map every significant nutrient source draining into the lake\'s watershed before any intervention can be sensibly proposed.\n\n'
   'Their survey identifies three major contributors. First, roughly 40% of the watershed\'s land is row-crop farmland, where fertilizer is applied each spring; soil testing shows a meaningful fraction runs off into feeder streams after heavy spring rains, before crops have grown enough to absorb it. Second, a cluster of older septic systems serving about 300 homes along the lake\'s eastern shore was installed decades before current standards, and several are suspected of leaking partially treated wastewater into groundwater that reaches the lake. Third, the town\'s stormwater system, which was not originally designed with nutrient control in mind, channels runoff from streets and lawns (including fertilized lawns) directly into the lake through a single large outflow pipe.\n\n'
   'The students estimate relative nutrient contributions: roughly 55% of the nitrogen load from farmland runoff, 25% from the aging septic systems, and 20% from the stormwater outflow — though they note these estimates carry real uncertainty, since nutrient loading is genuinely difficult to measure precisely across a whole watershed.')),
  ('Field Report, Part 2: Comparing Three Proposed Interventions', (
   'Based on the source mapping, the town council is presented with three intervention options, each with different projected effectiveness and cost, and asked to choose how to allocate a limited environmental budget.\n\n'
   'Option 1, a farmland buffer-strip program, would pay participating farmers to leave a strip of unfertilized native vegetation between crop fields and feeder streams, which studies show can capture a substantial share of runoff nutrients before they reach the water. Projected cost: $180,000 over three years, removing an estimated 8,000 lbs of nitrogen per year once fully established, though it requires voluntary farmer participation and full benefits take two to three years to appear as vegetation establishes.\n\n'
   'Option 2, a septic system upgrade program, would provide grants covering most of the cost for the 300 eastern-shore homes to replace aging septic systems with modern, better-treating systems. Projected cost: $2,400,000 total (homes cover a small remaining share), removing an estimated 2,200 lbs of nitrogen per year, with benefits appearing almost immediately after each system is replaced, though the town cannot force any homeowner to participate.\n\n'
   'Option 3, a stormwater retrofit, would add nutrient-capturing infrastructure to the town\'s single large outflow pipe. Projected cost: $310,000, removing an estimated 1,600 lbs of nitrogen per year, with benefits appearing as soon as construction finishes, and no dependence on voluntary participation since it is entirely within town control.\n\n'
   'The council has enough budget for only one option this cycle, and asks the environmental science team to recommend one, using evidence rather than which problem feels most visible.'))],
 [('Define "watershed" using the lesson\'s own wording, and explain why it matters that fertilizer applied far from the lake can still affect the lake.', 'A watershed is the land area that drains into a shared body of water; because runoff from anywhere in that land area eventually reaches the water, fertilizer applied on farmland far from the lake\'s shore can still contribute nutrients that reach the lake through streams and groundwater.'),
  ('Trace the eutrophication mechanism in order, from excess nutrients to fish kill, using the lesson\'s own steps.', 'Excess nitrogen/phosphorus reach the water and fuel an algal bloom; when the algae die, decomposing bacteria consume dissolved oxygen; the resulting hypoxic (low-oxygen) zone cannot support fish and other aquatic life that cannot leave in time.'),
  ('List the three nutrient sources identified in the Lake Clearview watershed and their estimated share of the nitrogen load.', 'Farmland runoff (~55%), aging septic systems (~25%), and the stormwater outflow (~20%).'),
  ('Calculate the cost-effectiveness (dollars per pound of nitrogen removed per year) for each of the three proposed options, showing your work.', 'Option 1: $180,000 ÷ 8,000 lbs/yr ≈ $22.50/lb. Option 2: $2,400,000 ÷ 2,200 lbs/yr ≈ $1,090.91/lb. Option 3: $310,000 ÷ 1,600 lbs/yr ≈ $193.75/lb.'),
  ('Based on your cost-effectiveness calculations, which single option removes the most nitrogen per dollar spent?', 'Option 1, the farmland buffer-strip program, at approximately $22.50 per pound of nitrogen removed per year — far more cost-effective than Options 2 or 3.'),
  ('Explain why Option 1\'s low cost-per-pound alone might not make it the automatically "correct" choice, using at least one specific tradeoff mentioned in the passage.', 'Option 1 depends on voluntary farmer participation (it could underperform if farmers don\'t sign up) and takes two to three years for full benefits to appear, unlike Option 3\'s immediate, guaranteed effect once built — cost-effectiveness alone does not capture reliability or timing.'),
  ('With a partner, discuss: why might the town council be tempted to choose the stormwater retrofit (Option 3) even though it is not the most cost-effective option?', 'The stormwater outflow pipe is a single, visible, directly town-controlled source, which may feel like the most obvious or politically satisfying target to "fix," even though the data shows farmland runoff contributes a larger share of the nutrient load and Option 1 removes more nitrogen per dollar.'),
  ('With a partner, evaluate Option 2 (septic upgrades): is its high cost-per-pound justified by any benefit the other options don\'t offer? Explain your reasoning.', 'Answers vary; a reasonable case notes Option 2 may address other concerns beyond nitrogen alone (e.g., pathogen contamination, groundwater quality, property values for the 300 homes), which the pure cost-per-pound-of-nitrogen metric does not capture — a fuller evaluation might weigh these unmeasured benefits against the high cost.'),
  ('Explain why the students note their source estimates (55/25/20%) "carry real uncertainty." Why does this matter for the council\'s decision?', 'Nutrient loading across a whole watershed is genuinely difficult to measure precisely, since it depends on rainfall patterns, soil conditions, and other variable factors; if the true farmland share were significantly different than estimated, the relative case for Option 1 could weaken or strengthen accordingly, so the council should treat the recommendation as evidence-based but not certain.'),
  ('Using only the evidence given, write a one-paragraph recommendation to the town council, naming your chosen option and citing at least two specific numbers from the passage.', 'Answers vary; must recommend one specific option and support it with at least two specific figures (cost, removal rate, cost-effectiveness, or timeline) drawn accurately from the passage.'),
  ('Propose a combined or phased plan using more than one intervention, if the town could secure additional funding beyond this cycle\'s budget. Justify your sequencing.', 'Answers vary; must propose a specific combination or order (e.g., start Option 1 for cost-effectiveness while its benefits establish over time, then add Option 3 for its immediate, dependable effect) with a reasoned justification.'),
  ('Explain why "removing more nitrogen per dollar" and "removing more nitrogen in total" are not necessarily the same ranking, using the numbers in this case.', 'Option 1 removes both the most total nitrogen (8,000 lbs/yr) and is the most cost-effective per dollar, but in principle these two measures could rank options differently — a very expensive option could still remove more total pounds than a cheap one if its absolute scale were large enough, even while being less efficient per dollar spent.'),
  ('Identify one nutrient source NOT mentioned in this case that could plausibly also contribute to a real lake\'s eutrophication, and explain your reasoning.', 'Answers vary; must propose a plausible additional source (e.g., golf course fertilizer, industrial discharge, atmospheric deposition, pet waste) and briefly explain how it could introduce nitrogen or phosphorus to the watershed.'),
  ('Explain why "voluntary farmer participation" is identified as a specific risk to Option 1\'s projected effectiveness, and propose one way the program could reduce that risk.', 'If farmers do not enroll enough acreage in the buffer-strip program, the actual nitrogen removed could fall short of the 8,000 lbs/yr projection, since the projection assumes a certain participation level; a way to reduce this risk could include raising payment incentives, simplifying enrollment, or targeting outreach to the farms contributing the most runoff.'),
  ('A classmate says "the septic systems must be the real problem, since old infrastructure sounds the most obviously broken." Evaluate this claim using the data in the passage.', 'The data shows septic systems contribute about 25% of the nitrogen load, less than farmland\'s 55%, and Option 2\'s cost-effectiveness is far worse than Option 1\'s; "sounds obviously broken" is an intuitive framing, not evidence, and the passage\'s numbers point to farmland as the larger and more cost-effective target.'),
  ('Explain the relationship between a watershed\'s size/land use and the difficulty of managing nutrient pollution, using evidence from this case.', 'Because a watershed integrates runoff from every type of land use within it (farmland, residential septic systems, town infrastructure), managing nutrient pollution requires coordinating across multiple, very different kinds of sources and property owners rather than targeting a single, easily controlled point, making watershed management inherently more complex than a single-source pollution problem.'),
  ('Write a short paragraph (4-5 sentences) explaining eutrophication to a town resident with no science background, without using the word "eutrophication."', 'Answers vary; must accurately convey the causal chain (excess nutrients → algae growth → algae death and decomposition → oxygen loss → fish kill) in accessible language.'),
  ('Explain why timing (spring fertilizer application before crops are established) makes farmland runoff worse, connecting it to the eutrophication mechanism.', 'Freshly applied fertilizer sits on bare or newly planted soil with little root structure to absorb it, so heavy spring rain can wash a larger share of it into streams than it would later in the season once crops are established and actively taking up nutrients, directly increasing the nutrient load feeding eutrophication downstream.'),
  ('Explain what would happen to the lake if the town did nothing and all three sources continued at current estimated rates. Use the term "nutrient load" in your answer.', 'The total nutrient load reaching the lake would remain high, continuing to fuel algal blooms and the eutrophication cycle; without any reduction in nutrient load, hypoxic dead zones and fish kills like the one two summers ago would likely continue or worsen over time.'),
  ('Self-assessment: which part of this lesson do you feel most confident explaining — the eutrophication mechanism, or the cost-effectiveness comparison — and which do you want to review again?', 'Answers vary; must name one specific part of the lesson for each half of the question.')],
 '90-minute session',
 800,
 vocab=[
   ('watershed', 'the land area that drains into a shared body of water'),
   ('eutrophication', 'nutrient-driven algal growth leading to oxygen loss'),
   ('hypoxic', 'low in dissolved oxygen; unable to support most aquatic life'),
   ('nutrient load', 'the total amount of nitrogen/phosphorus entering a water body'),
   ('cost-effectiveness', 'benefit achieved per dollar spent, not just total cost'),
   ('runoff', 'water flowing over land, carrying dissolved and loose material with it'),
 ],
 pacing='Warm-up 8 min · read both field-report passages + vocabulary 15 min · guided source-mapping organizer 18 min · partner cost-effectiveness discussion 18 min · independent practice 22 min · extension work 5 min · assessment 4 min.')

